","requires":["oa-s3-lesson-10"]},{"topicId":"oa-s4-lesson-13","requires":["oa-s4-lesson-12"]},{"topicId":"oa-s4-lesson-14","requires":["oa-s4-lesson-13"]},{"topicId":"oa-s5-lesson-16","requires":["oa-s5-lesson-15"]},{"topicId":"oa-s5-lesson-17","requires":["oa-s5-lesson-16"]},{"topicId":"oa-s6-lesson-19","requires":["oa-s6-lesson-18"]},{"topicId":"oa-s6-lesson-20","requires":["oa-s6-lesson-19"]},{"topicId":"oa-s6-lesson-21","requires":["oa-s6-lesson-20"]},{"topicId":"oa-s7-lesson-23","requires":["oa-s7-lesson-22"]},{"topicId":"oa-s7-lesson-24","requires":["oa-s7-lesson-23"]},{"topicId":"oa-s7-lesson-25","requires":["oa-s7-lesson-24"]},{"topicId":"oa-s7-lesson-26","requires":["oa-s7-lesson-25"]},{"topicId":"oa-s8-lesson-28","requires":["oa-s8-lesson-27"]},{"topicId":"oa-s8-lesson-29","requires":["oa-s8-lesson-28"]},{"topicId":"oa-s8-lesson-30","requires":["oa-s8-lesson-29"]},{"topicId":"oa-s9-lesson-32","requires":["oa-s9-lesson-31"]},{"topicId":"oa-s9-lesson-33","requires":["oa-s9-lesson-32"]},{"topicId":"oa-s9-lesson-34","requires":["oa-s9-lesson-33"]},{"topicId":"oa-s10-lesson-36","requires":["oa-s10-lesson-35"]},{"topicId":"oa-s10-lesson-37","requires":["oa-s10-lesson-36"]},{"topicId":"oa-s11-lesson-39","requires":["oa-s11-lesson-38"]}]}'::jsonb,1) on conflict(id) do update set name=excluded.name,short_name=excluded.short_name,description=excluded.description,sort_order=excluded.sort_order,implementation=excluded.implementation,study_view=excluded.study_view,capabilities=excluded.capabilities,routes=excluded.routes,stats=excluded.stats,learning_config=excluded.learning_config,manifest_version=greatest(public.spark_subjects.manifest_version,excluded.manifest_version),updated_at=now();
