insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s1-lesson-01','oa-section-1','What the office does and how a business is organised','An office is the information and coordination centre of an organisation. It receives facts, checks and processes them, stores records and sends useful information to the people who need it. A customer order starts as data: a name, product code and quantity. After checking stock and price, the office produces information that the warehouse can act on. The office also supports production, distribution, buying, selling, payments and the control of the business. It is a function, so it can operate in a building, from home or across several locations.',0,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":12,"section":1,"objectiveCodes":["OA1.1","OA1.2"]},"lesson":{"introduction":"An office is the information and coordination centre of an organisation. It receives facts, checks and processes them, stores records and sends useful information to the people who need it. A customer order starts as data: a name, product code and quantity. After checking stock and price, the office produces information that the warehouse can act on. The office also supports production, distribution, buying, selling, payments and the control of the business. It is a function, so it can operate in a building, from home or across several locations.","objectives":["describe the role and functions of the office in business activities","describe how office structure and activity may be organised according to the characteristics of a business"],"sections":[{"title":"How it works","paragraphs":["The business''s purpose and goals influence its office. A small plumbing firm may have one clerk answering calls, booking jobs and preparing invoices. A large hotel may separate reception, purchasing, human resources and accounts. Centralisation puts a function under one common team; decentralisation places responsibility closer to individual branches or departments. Centralisation can reduce duplication and improve consistency; decentralisation can make local responses faster. Neither arrangement is automatically best.","An organisation chart shows positions and their relationships. Read a solid vertical line as a reporting relationship, not as a friendship. Authority is the right to direct work; responsibility is the duty to do it; accountability means being answerable for the result. A clerk should know whom to ask for approval and where to refer an exception. Clear lines of communication prevent two departments from giving conflicting instructions."]},{"title":"A practical office example","paragraphs":["At a Kingston furniture company, the sales clerk records an order, the stores clerk confirms availability, dispatch schedules delivery and accounts issues an invoice. If stores reports that an item is unavailable, sales must agree a new arrangement with the customer before dispatch promises a date. Trace the information through all four departments: a delay in one office affects the whole service."]},{"title":"Avoid this mistake","paragraphs":["Do not describe an office as only a room containing desks. Explain the work it does and how that work supports the organisation. An organisation chart shows posts; it does not show every informal conversation."]}],"keyPoints":["An office is the information and coordination centre of an organisation.","The business''s purpose and goals influence its office.","An organisation chart shows positions and their relationships."],"summary":"The stock record turns a customer''s request into a workable order. Checking prevents an unavailable item being promised and lets sales arrange an alternative before dispatch plans the delivery.","check":{"question":"Why should a sales clerk check stock before confirming delivery?","answer":"The stock record turns a customer''s request into a workable order. Checking prevents an unavailable item being promised and lets sales arrange an alternative before dispatch plans the delivery."},"flashcards":[{"id":"OA1.1","front":"Describe the role and functions of the office in business activities.","back":"The office collects, processes, stores and communicates information, coordinates work and supports business transactions and control. Its work connects departments such as sales, stores, dispatch and accounts.","objectiveCodes":["OA1.1"]},{"id":"OA1.2","front":"Describe how office structure and activity may be organised according to the characteristics of a business.","back":"Office structure depends on the size and nature of the business. An organisation chart shows posts and reporting relationships. Centralisation combines control of a function; decentralisation places responsibility closer to individual departments or branches.","objectiveCodes":["OA1.2"]},{"id":"oa-check-1","front":"Why should a sales clerk check stock before confirming delivery?","back":"The stock record turns a customer''s request into a workable order. Checking prevents an unavailable item being promised and lets sales arrange an alternative before dispatch plans the delivery.","objectiveCodes":["OA1.1","OA1.2"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s1-lesson-02','oa-section-1','Office layouts, ergonomics and safe working','A cellular office uses separate rooms. It offers privacy and fewer interruptions, which may suit confidential interviews, but can cost more and slow communication. An open-plan office puts several workers in a shared space. It can improve supervision and teamwork, but noise and lack of privacy need control. A landscaped layout uses planned work areas, furniture and screens to organise an open space. A virtual office coordinates work through communications technology without requiring everyone to occupy one permanent office.',1,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":13,"section":1,"objectiveCodes":["OA1.3","OA1.4"]},"lesson":{"introduction":"A cellular office uses separate rooms. It offers privacy and fewer interruptions, which may suit confidential interviews, but can cost more and slow communication. An open-plan office puts several workers in a shared space. It can improve supervision and teamwork, but noise and lack of privacy need control. A landscaped layout uses planned work areas, furniture and screens to organise an open space. A virtual office coordinates work through communications technology without requiring everyone to occupy one permanent office.","objectives":["compare different types of office arrangements","examine the ergonomics of the office as it relates to comfort, health and safety issues"],"sections":[{"title":"How it works","paragraphs":["Judge a layout against the task. Reception should be easy to find without giving visitors unrestricted access to staff or records. Keep frequently used equipment within convenient reach and arrange a sensible route from incoming work to completed work. A clear aisle is not spare storage space. Consider lighting, ventilation, temperature, accessibility, noise, cable management and emergency exits as well as appearance.","Ergonomics means fitting the work and equipment to the person. Adjust a chair so the back is supported and feet rest securely; position the keyboard and mouse so shoulders and wrists are relaxed. Put the screen where it can be read without bending the neck or fighting glare. Alternate tasks and take appropriate movement breaks. Report damaged electrical equipment, clean up spills promptly and follow the organisation''s fire, first-aid and evacuation procedures."]},{"title":"A practical office example","paragraphs":["A receptionist works beside a bright window and twists repeatedly to reach a shared printer. Move or shade the screen to reduce glare, position frequently used items within easy reach and rearrange the workstation so routine tasks do not require repeated twisting. The aim is to reduce strain while keeping the visitor route clear."]},{"title":"Avoid this mistake","paragraphs":["Do not recommend an expensive open-plan office simply because it looks modern. Link the choice to privacy, communication, cost and the actual work. Ergonomics includes the task and environment, not just buying an adjustable chair."]}],"keyPoints":["A cellular office uses separate rooms.","Judge a layout against the task.","Ergonomics means fitting the work and equipment to the person."],"summary":"A private room protects confidential discussion and reduces interruptions. The reason must relate to the work being done.","check":{"question":"Give one reason for using a private room for a personnel interview.","answer":"A private room protects confidential discussion and reduces interruptions. The reason must relate to the work being done."},"flashcards":[{"id":"OA1.3","front":"Compare different types of office arrangements.","back":"Cellular offices provide separate rooms and privacy. Open-plan offices share space and can improve teamwork but need noise and privacy controls. Landscaped offices organise shared space; virtual offices coordinate work through communications technology.","objectiveCodes":["OA1.3"]},{"id":"OA1.4","front":"Examine the ergonomics of the office as it relates to comfort, health and safety issues.","back":"Fit the workstation and task to the person: suitable seating, screen and keyboard position, lighting, ventilation and movement breaks reduce strain. Keep routes clear, control cables and follow safety and emergency procedures.","objectiveCodes":["OA1.4"]},{"id":"oa-check-2","front":"Give one reason for using a private room for a personnel interview.","back":"A private room protects confidential discussion and reduces interruptions. The reason must relate to the work being done.","objectiveCodes":["OA1.3","OA1.4"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s1-lesson-03','oa-section-1','Choosing and caring for office resources','Office resources include people, information, money, furniture, stationery, equipment, software, time and space. They work together. A scanner does not improve a records system unless someone scans accurately, names files consistently and stores them securely. A printer with a low purchase price can still be costly if ink, repairs and wasted paper are expensive.',2,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":13,"section":1,"objectiveCodes":["OA1.5","OA1.6"]},"lesson":{"introduction":"Office resources include people, information, money, furniture, stationery, equipment, software, time and space. They work together. A scanner does not improve a records system unless someone scans accurately, names files consistently and stores them securely. A printer with a low purchase price can still be costly if ink, repairs and wasted paper are expensive.","objectives":["describe the contribution of various types of resources to the office environment","discuss the factors to consider when selecting different types of resources for the office environment"],"sections":[{"title":"How it works","paragraphs":["Begin a purchasing decision with the need: what work must be done, how often, by whom and to what standard? Compare capacity, reliability, compatibility, running costs, maintenance, warranty, supplier support, ease of use, accessibility and environmental impact. Consider whether to buy, rent, lease or outsource. A high-volume office may justify a multifunction machine; a small office may use a simpler printer and a secure external service for occasional specialist work.","Care for resources through authorised use, staff training, scheduled maintenance, accurate stock records and sensible energy use. Keep liquids away from equipment and do not attempt an electrical repair without authority and competence. Protect information through controlled access, backups and secure disposal. Reducing waste should not mean reusing paper that exposes confidential information."]},{"title":"Know which piece of equipment fits the job","paragraphs":["A guillotine cuts paper accurately in a straight line; use its guard and approved handling procedure. A shredder destroys paper into small pieces for secure disposal, although the required destruction standard depends on the record. A laminator seals a document in protective film. A binding machine joins the pages of a booklet or report. A labeller produces consistent labels for files, shelves or equipment.","A multifunction printer combines tasks such as printing, copying and scanning. A risograph is a digital duplicating machine useful for producing many copies of suitable material. A scanner converts a document or image into a digital file; check the resolution, orientation and legibility before saving. A plotter produces large, precise drawings such as plans rather than ordinary office letters.","A digital camera captures images, a projector displays material to an audience and an interactive whiteboard or smartboard can support presentation and annotation. Productivity software includes word processing, spreadsheets, databases, presentation tools and scheduling applications. Match the function to the task: use a spreadsheet to calculate a stock total, not merely because a computer is available."]},{"title":"A practical office example","paragraphs":["Two printers both cost $45,000. Printer A costs $4 per page and Printer B costs $2.50 per page. At 8,000 pages, the running costs are $32,000 and $20,000. Before choosing B, also check its speed, warranty, network compatibility and the availability of consumables. The cheaper operating cost is useful evidence, not the only decision factor."]},{"title":"Avoid this mistake","paragraphs":["The cheapest purchase is not always the lowest total cost. Do not confuse a resource''s contribution with a list of brand names or assume that every task requires new technology."]}],"keyPoints":["Office resources include people, information, money, furniture, stationery, equipment, software, time and space.","Begin a purchasing decision with the need: what work must be done, how often, by whom and to what standard?","Care for resources through authorised use, staff training, scheduled maintenance, accurate stock records and sensible energy use."],"summary":"The scanner must work with the existing computers, file formats and records software. Incompatible equipment can create extra cost or prevent the intended work from being completed.","check":{"question":"Why should an office check software compatibility before purchasing a new scanner?","answer":"The scanner must work with the existing computers, file formats and records software. Incompatible equipment can create extra cost or prevent the intended work from being completed."},"flashcards":[{"id":"OA1.5","front":"Describe the contribution of various types of resources to the office environment.","back":"People, information, money, time, space, furniture, stationery, equipment and software support office work together. A resource is useful only when it meets the task and is used accurately and responsibly.","objectiveCodes":["OA1.5"]},{"id":"OA1.6","front":"Discuss the factors to consider when selecting different types of resources for the office environment.","back":"Compare the task, capacity, compatibility, reliability, total cost, maintenance, support, accessibility and environmental impact. Consider buying, renting, leasing or outsourcing where appropriate, rather than selecting only by purchase price.","objectiveCodes":["OA1.6"]},{"id":"oa-check-3","front":"Why should an office check software compatibility before purchasing a new scanner?","back":"The scanner must work with the existing computers, file formats and records software. Incompatible equipment can create extra cost or prevent the intended work from being completed.","objectiveCodes":["OA1.5","OA1.6"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s1-lesson-04','oa-section-1','Professional behaviour and good working relationships','Employers need technical skills and dependable conduct. Office staff should communicate clearly, handle numbers and documents accurately, organise time, use relevant technology and solve routine problems. Desirable attitudes include courtesy, initiative, willingness to learn, punctuality, honesty, discretion and respect for others. Initiative means taking a sensible action within your authority; it does not mean changing an approved procedure without permission.',3,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":14,"section":1,"objectiveCodes":["OA1.7","OA1.8"]},"lesson":{"introduction":"Employers need technical skills and dependable conduct. Office staff should communicate clearly, handle numbers and documents accurately, organise time, use relevant technology and solve routine problems. Desirable attitudes include courtesy, initiative, willingness to learn, punctuality, honesty, discretion and respect for others. Initiative means taking a sensible action within your authority; it does not mean changing an approved procedure without permission.","objectives":["propose desirable skills, attitudes and attributes of office personnel","assess the value of good human relationships to office efficiency"],"sections":[{"title":"How it works","paragraphs":["Good human relationships make work easier to coordinate. Listen without interrupting, clarify requests, share information with authorised colleagues and give constructive feedback about the work rather than attacking a person. Respect cultural differences and accessibility needs. When duties conflict, explain the problem to the appropriate supervisor and agree priorities instead of silently missing a deadline.","Confidentiality is especially important around customers, pay records, appointments and business plans. Discuss sensitive matters only with people entitled to know. Social responsibility includes considerate use of resources and fair treatment of customers and colleagues. A professional social-media presence also matters: do not post workplace photographs, customer details or internal complaints without authorisation."]},{"title":"A practical office example","paragraphs":["An accounts clerk needs a signed delivery record before paying a supplier, but dispatch has not returned it. A useful message identifies the order, explains the deadline and asks when the record can be supplied. Blaming dispatch in a group chat creates friction without solving the problem. Agree an action, record it and follow up courteously."]},{"title":"Avoid this mistake","paragraphs":["Being friendly does not justify sharing private information. Being assertive means expressing a need clearly and respectfully; aggression and personal criticism usually damage cooperation."]}],"keyPoints":["Employers need technical skills and dependable conduct.","Good human relationships make work easier to coordinate.","Confidentiality is especially important around customers, pay records, appointments and business plans."],"summary":"Identify a routine problem, gather the relevant facts and take an approved action or propose a solution to the supervisor. Obtain approval before making commitments outside the clerk''s authority.","check":{"question":"How can a clerk show initiative without exceeding authority?","answer":"Identify a routine problem, gather the relevant facts and take an approved action or propose a solution to the supervisor. Obtain approval before making commitments outside the clerk''s authority."},"flashcards":[{"id":"OA1.7","front":"Propose desirable skills, attitudes and attributes of office personnel.","back":"Office personnel need communication, technology, organisation and numeracy skills, with honesty, accuracy, courtesy, punctuality, discretion, initiative and willingness to learn. Initiative must remain within authority.","objectiveCodes":["OA1.7"]},{"id":"OA1.8","front":"Assess the value of good human relationships to office efficiency.","back":"Courtesy, listening, clear responsibilities, reliable information and respectful problem-solving improve cooperation and reduce delays and conflict. Good relationships must still respect confidentiality and approved procedures.","objectiveCodes":["OA1.8"]},{"id":"oa-check-4","front":"How can a clerk show initiative without exceeding authority?","back":"Identify a routine problem, gather the relevant facts and take an approved action or propose a solution to the supervisor. Obtain approval before making commitments outside the clerk''s authority.","objectiveCodes":["OA1.7","OA1.8"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s2-lesson-05','oa-section-2','Reception: the organisation''s first point of contact','Reception connects the visitor with the organisation. A courteous, organised welcome can build confidence before a customer meets anyone else. Poor handling can lead to lost appointments, security problems and complaints. Reception staff therefore support both customer goodwill and the efficient movement of information.',4,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":17,"section":2,"objectiveCodes":["OA2.1","OA2.2"]},"lesson":{"introduction":"Reception connects the visitor with the organisation. A courteous, organised welcome can build confidence before a customer meets anyone else. Poor handling can lead to lost appointments, security problems and complaints. Reception staff therefore support both customer goodwill and the efficient movement of information.","objectives":["assess the contribution of the reception desk to the welfare of the organisation","identify the duties, responsibilities and attributes of a receptionist"],"sections":[{"title":"How it works","paragraphs":["A receptionist greets visitors, establishes the purpose of a visit, checks appointments, informs the host and directs or accompanies visitors according to procedure. Other duties can include operating the telephone system, taking messages, arranging appointments, handling enquiries and keeping the reception area orderly. Ask questions tactfully and collect only the information needed for the task.","Follow the visitor-control procedure: verify the visitor''s identity and appointment, contact the host, issue a pass if required and record arrival and departure. An appointment does not give a visitor permission to wander through the office. If a host is delayed, explain politely, offer an appropriate waiting arrangement and seek guidance. Be calm with an upset visitor, listen and refer matters beyond your authority. Do not promise an outcome simply to end the conversation."]},{"title":"A practical office example","paragraphs":["A customer arrives early for a 10 a.m. appointment with Ms James. Welcome the customer, confirm the name and appointment, notify Ms James and explain where to wait. If another person asks whom the customer is seeing, follow confidentiality procedures rather than announcing the purpose of the visit across the room."]},{"title":"Avoid this mistake","paragraphs":["Do not treat reception as only answering the telephone. Courtesy, security, accurate information and orderly visitor handling all contribute to the organisation''s welfare."]}],"keyPoints":["Reception connects the visitor with the organisation.","A receptionist greets visitors, establishes the purpose of a visit, checks appointments, informs the host and directs or accompanies visitors according to procedure.","Follow the visitor-control procedure: verify the visitor''s identity and appointment, contact the host, issue a pass if required and record arrival and departure."],"summary":"Establish the visitor''s identity and purpose, contact the appropriate employee and follow the visitor procedure. Do not send the visitor directly into restricted areas or guarantee that the employee will be available.","check":{"question":"What should a receptionist do when a visitor arrives without an appointment?","answer":"Establish the visitor''s identity and purpose, contact the appropriate employee and follow the visitor procedure. Do not send the visitor directly into restricted areas or guarantee that the employee will be available."},"flashcards":[{"id":"OA2.1","front":"Assess the contribution of the reception desk to the welfare of the organisation.","back":"Reception builds first impressions, directs visitors and enquiries, supports security, relays information and helps staff keep appointments. Accurate, courteous handling supports customer goodwill and office efficiency.","objectiveCodes":["OA2.1"]},{"id":"OA2.2","front":"Identify the duties, responsibilities and attributes of a receptionist.","back":"A receptionist welcomes and checks visitors, contacts hosts, follows access procedures, handles enquiries and telephone calls, records messages and appointments and keeps the reception area orderly. Courtesy, tact, organisation and discretion are essential.","objectiveCodes":["OA2.2"]},{"id":"oa-check-5","front":"What should a receptionist do when a visitor arrives without an appointment?","back":"Establish the visitor''s identity and purpose, contact the appropriate employee and follow the visitor procedure. Do not send the visitor directly into restricted areas or guarantee that the employee will be available.","objectiveCodes":["OA2.1","OA2.2"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s2-lesson-06','oa-section-2','Telephone calls and useful written messages','Answer promptly using the organisation''s approved greeting, identify the organisation and yourself where required, speak clearly and listen. Keep a professional tone even when a caller is impatient. Before transferring a call, establish whom the caller needs and explain the transfer. Ask permission before putting someone on hold, return regularly and offer an alternative when the wait will be long.',5,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":18,"section":2,"objectiveCodes":["OA2.3"]},"lesson":{"introduction":"Answer promptly using the organisation''s approved greeting, identify the organisation and yourself where required, speak clearly and listen. Keep a professional tone even when a caller is impatient. Before transferring a call, establish whom the caller needs and explain the transfer. Ask permission before putting someone on hold, return regularly and offer an alternative when the wait will be long.","objectives":["describe proper techniques for receiving and relaying messages by telephone"],"sections":[{"title":"How it works","paragraphs":["A message should normally include the date and time, caller''s name and organisation, intended recipient, contact details, the substance of the call, the action requested and the name of the person taking the message. Write down names, numbers, dates and references carefully. Read important details back to the caller: a single wrong digit can make the whole message unusable.","Distinguish an exact request from your own interpretation. If the caller asks for an update on order 417 before 3 p.m., do not write only ''called about an order'' and do not promise delivery. Mark urgency accurately, relay the message promptly through the approved channel and protect confidential information. For an outgoing call, prepare the number, purpose, documents and questions before dialling; identify yourself and record any agreed action."]},{"title":"A practical office example","paragraphs":["Denise Davis calls for Mr Brown about purchase order 417 and requests a return call on 876-555-0147 before 3 p.m. A useful message preserves all five details: caller, recipient, reference, callback number and requested time. Read the number back and check whether ''before 3 p.m.'' is today before ending the call."]},{"title":"Avoid this mistake","paragraphs":["Do not substitute your own promise for a caller''s request. Writing a neat message is not enough if its number or deadline is wrong. Personal calls and background conversation should not interfere with service."]}],"keyPoints":["Answer promptly using the organisation''s approved greeting, identify the organisation and yourself where required, speak clearly and listen.","A message should normally include the date and time, caller''s name and organisation, intended recipient, contact details, the substance of the call, the action requested and the name of the person taking the message.","Distinguish an exact request from your own interpretation."],"summary":"It does not identify the caller, contact details, purpose, time or action needed. A useful message lets the recipient return the correct call and deal with the actual request.","check":{"question":"Why is ''Please call Mr Brown'' an inadequate message when several people called?","answer":"It does not identify the caller, contact details, purpose, time or action needed. A useful message lets the recipient return the correct call and deal with the actual request."},"flashcards":[{"id":"OA2.3","front":"Describe proper techniques for receiving and relaying messages by telephone.","back":"Use an approved greeting, listen, confirm important details and transfer or hold calls courteously. Record the caller, recipient, contact number, date and time, message, requested action and person taking it. Relay it promptly.","objectiveCodes":["OA2.3"]},{"id":"oa-check-6","front":"Why is ''Please call Mr Brown'' an inadequate message when several people called?","back":"It does not identify the caller, contact details, purpose, time or action needed. A useful message lets the recipient return the correct call and deal with the actual request.","objectiveCodes":["OA2.3"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s2-lesson-07','oa-section-2','Appointment diaries and reminder systems','An appointment diary records agreed meetings and protects the executive''s time. Establish the purpose, people involved, preferred date, expected length, location or meeting link and any preparation required. Check existing commitments, travel time, opening hours and the executive''s instructions before offering a slot. Confirm the agreed details with everyone concerned.',6,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":18,"section":2,"objectiveCodes":["OA2.4","OA2.5"]},"lesson":{"introduction":"An appointment diary records agreed meetings and protects the executive''s time. Establish the purpose, people involved, preferred date, expected length, location or meeting link and any preparation required. Check existing commitments, travel time, opening hours and the executive''s instructions before offering a slot. Confirm the agreed details with everyone concerned.","objectives":["manage appointments for an executive using electronic or manual systems","explain the importance and use of electronic and manual reminder systems"],"sections":[{"title":"How it works","paragraphs":["A paper diary is quick to consult and does not depend on a device, but changes must be recorded clearly and securely. An electronic calendar can share availability, send invitations and reminders and help detect clashes, but access permissions, connectivity and time-zone settings must be correct. Avoid keeping two conflicting diaries without a clear procedure for synchronising them.","A reminder or tickler system brings work back to attention on the date action is needed. It may use dated paper folders, a diary entry or an electronic task notification. Set a reminder early enough to prepare, not merely at the final deadline. When an appointment changes, amend the original entry, notify the people affected, update associated arrangements and confirm the replacement. Never silently delete a commitment that another person still expects to attend."]},{"title":"A practical office example","paragraphs":["A manager has a meeting from 9:00 to 9:45 and needs 20 minutes to travel to a customer. A new appointment at 10:00 is unsuitable because only 15 minutes are available. Offer a later slot or change another arrangement with approval. Add a preparation reminder for the documents needed before departure."]},{"title":"Avoid this mistake","paragraphs":["A diary entry records an appointment; a reminder prompts action. Do not assume that a calendar invitation has been accepted or ignore travel and preparation time because the meeting itself fits in the gap."]}],"keyPoints":["An appointment diary records agreed meetings and protects the executive''s time.","A paper diary is quick to consult and does not depend on a device, but changes must be recorded clearly and securely.","A reminder or tickler system brings work back to attention on the date action is needed."],"summary":"Update the diary and reminders, notify participants, confirm the new details and amend rooms, travel, equipment and documents associated with the original appointment.","check":{"question":"What should be updated when an executive reschedules a meeting?","answer":"Update the diary and reminders, notify participants, confirm the new details and amend rooms, travel, equipment and documents associated with the original appointment."},"flashcards":[{"id":"OA2.4","front":"Manage appointments for an executive using electronic or manual systems.","back":"Check availability, purpose, duration, location and preparation or travel time before agreeing an appointment. Record and confirm the details; notify everyone affected and update associated arrangements when it changes.","objectiveCodes":["OA2.4"]},{"id":"OA2.5","front":"Explain the importance and use of electronic and manual reminder systems.","back":"A reminder or tickler system brings a task back to attention when action is needed. Paper date folders, diaries and electronic reminders help staff meet deadlines if entries are accurate, early enough and updated.","objectiveCodes":["OA2.5"]},{"id":"oa-check-7","front":"What should be updated when an executive reschedules a meeting?","back":"Update the diary and reminders, notify participants, confirm the new details and amend rooms, travel, equipment and documents associated with the original appointment.","objectiveCodes":["OA2.4","OA2.5"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s3-lesson-08','oa-section-3','Choose a communication channel that fits the message','Communication is successful when the receiver understands the intended message and can respond appropriately. Internal communication stays within the organisation; external communication connects it with customers, suppliers and the public. Downward communication gives instructions or information from a higher level, upward communication carries reports or feedback to management, and horizontal communication coordinates colleagues at a similar level. Oral, written, visual and electronic methods can serve any of these routes.',7,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":21,"section":3,"objectiveCodes":["OA3.1","OA3.2","OA3.3"]},"lesson":{"introduction":"Communication is successful when the receiver understands the intended message and can respond appropriately. Internal communication stays within the organisation; external communication connects it with customers, suppliers and the public. Downward communication gives instructions or information from a higher level, upward communication carries reports or feedback to management, and horizontal communication coordinates colleagues at a similar level. Oral, written, visual and electronic methods can serve any of these routes.","objectives":["describe the various channels of communication used in the office","discuss factors affecting the selection of communication channel","discuss the barriers to effective communication"],"sections":[{"title":"How it works","paragraphs":["Choose a method by considering urgency, confidentiality, cost, distance, available technology, the receiver''s needs and whether a permanent record is required. A telephone call is useful for an urgent clarification, but a written confirmation is better for preserving an agreed specification. An email can reach several authorised people quickly; it can also be overlooked, sent to the wrong address or forwarded without care. A meeting is useful when people need to discuss and decide, but unnecessary meetings consume working time.","Barriers include noise, jargon, language differences, a poor connection, incomplete information, the wrong channel, assumptions, unsuitable timing and emotional reactions. Reduce them by using plain language, choosing an appropriate time and place, checking facts and inviting feedback. A nod or a sent-email notification does not prove understanding. Ask the receiver to confirm a crucial date, quantity or next action in their own words."]},{"title":"Recognise the main written office messages","paragraphs":["A business letter is formal correspondence, often sent outside the organisation. It normally identifies the sender, date, addressee, salutation, subject where appropriate, message, complimentary close and signatory. Mention relevant enclosures and use a salutation and close that match the chosen style. A memorandum is an internal message; its heading usually states To, From, Date and Subject, followed by the purpose and action required.","A circular carries the same information to several recipients. A notice announces information or an event to its intended audience. A report presents organised information, findings and, where required, conclusions and recommendations. An email still needs a useful subject, correct recipients, clear content and the right attachments. The chosen format should help the recipient understand what happened and what to do next.","Visual communication uses items such as a chart, diagram, sign or image. Oral methods include face-to-face discussion, a telephone call and a presentation. Electronic methods can carry written, oral and visual content together. A video meeting is therefore an electronic channel that may contain speech, shared text and a chart; these categories are not always mutually exclusive."]},{"title":"A practical office example","paragraphs":["A supplier needs to know today whether to substitute blue folders for green ones. Call the authorised purchasing officer to resolve the urgent choice, then send the approved details in writing. A public social-media comment would be unsuitable because it exposes business information and may not reach the decision-maker."]},{"title":"Avoid this mistake","paragraphs":["Do not say that email is always the best method. Explain why a method suits this message and this receiver. Sending information is not the same as confirming that it was understood."]}],"keyPoints":["Communication is successful when the receiver understands the intended message and can respond appropriately.","Choose a method by considering urgency, confidentiality, cost, distance, available technology, the receiver''s needs and whether a permanent record is required.","Barriers include noise, jargon, language differences, a poor connection, incomplete information, the wrong channel, assumptions, unsuitable timing and emotional reactions."],"summary":"The call settles the issue quickly; the written follow-up preserves the exact agreement, responsibilities and deadline for both parties.","check":{"question":"Why might an urgent telephone agreement need a written follow-up?","answer":"The call settles the issue quickly; the written follow-up preserves the exact agreement, responsibilities and deadline for both parties."},"flashcards":[{"id":"OA3.1","front":"Describe the various channels of communication used in the office.","back":"Communication may be internal or external, upward, downward or horizontal, using oral, written, visual or electronic methods. The channel must reach the intended receiver and support understanding and appropriate feedback.","objectiveCodes":["OA3.1"]},{"id":"OA3.2","front":"Discuss factors affecting the selection of communication channel.","back":"Consider urgency, confidentiality, cost, distance, complexity, access to technology, audience needs and whether a permanent record is required. An urgent call may need written confirmation of the agreement.","objectiveCodes":["OA3.2"]},{"id":"OA3.3","front":"Discuss the barriers to effective communication.","back":"Noise, jargon, language differences, poor connections, incomplete information, assumptions and unsuitable timing can block understanding. Use plain language, reliable channels, suitable conditions and feedback to check meaning.","objectiveCodes":["OA3.3"]},{"id":"oa-check-8","front":"Why might an urgent telephone agreement need a written follow-up?","back":"The call settles the issue quickly; the written follow-up preserves the exact agreement, responsibilities and deadline for both parties.","objectiveCodes":["OA3.1","OA3.2","OA3.3"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s3-lesson-09','oa-section-3','Stationery and reliable sources of information','Stationery should suit the document and the way it will be handled. Letterheads identify the organisation; continuation sheets carry later pages; forms collect information in a consistent order; envelopes protect and address the contents. Consider paper size, weight, number of copies, printing method, storage, postage and confidentiality. Use the approved stationery and keep quantities under control.',8,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":23,"section":3,"objectiveCodes":["OA3.4","OA3.5"]},"lesson":{"introduction":"Stationery should suit the document and the way it will be handled. Letterheads identify the organisation; continuation sheets carry later pages; forms collect information in a consistent order; envelopes protect and address the contents. Consider paper size, weight, number of copies, printing method, storage, postage and confidentiality. Use the approved stationery and keep quantities under control.","objectives":["select appropriate types and sizes of stationery for a variety of uses","select relevant sources of information"],"sections":[{"title":"How it works","paragraphs":["A4 paper is commonly used for letters and reports; A5 can suit smaller notices or forms, while A3 provides more space for large charts. Select an envelope that accommodates the contents appropriately: a document that must remain flat needs a different choice from an ordinary folded letter. Window envelopes require the address to align correctly. Check the letter and enclosures before sealing; an attractive letterhead cannot correct a missing attachment.","Information sources include internal files, directories, manuals, official websites, reference books, databases, schedules, trade publications and people with relevant responsibility. Decide what fact is needed before searching. Check who produced the source, its date, accuracy, relevance and authority. A current supplier price list is useful for a quotation; an old invoice may show a historical price rather than the amount available today. Record the source when the information will be used in a report."]},{"title":"Choose paper and envelopes as a matching pair","paragraphs":["Common paper sizes include A4 (210 × 297 mm), A5 (148 × 210 mm) and A6 (105 × 148 mm). A5 is half an A4 sheet and A6 is half an A5 sheet. Letter paper is normally 8½ × 11 inches and legal paper 8½ × 14 inches. Letter and A4 are close in size but are not identical: the wrong printer or template setting can crop a document.","A C4 envelope accommodates A4 paper flat. C5 accommodates A5 flat or A4 folded once; C6 accommodates A6 flat. A DL envelope commonly takes an A4 letter folded into thirds. A window envelope reveals the address printed on the enclosed letter, so alignment matters. Select a mailing label large enough for a clear address and service information without covering a barcode or important handling instruction."]},{"title":"A practical office example","paragraphs":["A clerk prepares a board pack containing a letter and a large unfolded chart. Check the chart dimensions and the requirement to keep it flat before selecting the envelope. Obtain the current meeting date from the approved notice rather than reusing the date on an earlier pack. Match each material and source to its purpose."]},{"title":"Avoid this mistake","paragraphs":["Do not treat every search result as authoritative or assume that the largest paper size is always best. The question asks you to select and justify an appropriate resource."]}],"keyPoints":["Stationery should suit the document and the way it will be handled.","A4 paper is commonly used for letters and reports; A5 can suit smaller notices or forms, while A3 provides more space for large charts.","Information sources include internal files, directories, manuals, official websites, reference books, databases, schedules, trade publications and people with relevant responsibility."],"summary":"Use the carrier''s current schedule, checking the destination, weight and service. The old invoice describes a previous transaction and may no longer apply.","check":{"question":"Which is the better source for today''s delivery charge: an old customer invoice or the carrier''s current published schedule?","answer":"Use the carrier''s current schedule, checking the destination, weight and service. The old invoice describes a previous transaction and may no longer apply."},"flashcards":[{"id":"OA3.4","front":"Select appropriate types and sizes of stationery for a variety of uses.","back":"Choose stationery for the document, handling, printing, storage and postage needs. Match paper and envelope size, protect confidential contents and check the letter, address and enclosures before dispatch.","objectiveCodes":["OA3.4"]},{"id":"OA3.5","front":"Select relevant sources of information.","back":"Use relevant, authoritative and current sources. Internal records, approved manuals, directories, official sites and current supplier schedules serve different needs. Check accuracy and date, and record sources where appropriate.","objectiveCodes":["OA3.5"]},{"id":"oa-check-9","front":"Which is the better source for today''s delivery charge: an old customer invoice or the carrier''s current published schedule?","back":"Use the carrier''s current schedule, checking the destination, weight and service. The old invoice describes a previous transaction and may no longer apply.","objectiveCodes":["OA3.4","OA3.5"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s3-lesson-10','oa-section-3','Telecommunications and virtual office services','Telecommunication services allow offices to exchange voice, documents, images and data across distance. Examples include fixed and mobile telephone services, internet access, messaging, voice mail, video conferencing and data services. A virtual meeting can bring colleagues from different islands together without requiring travel, but its usefulness depends on preparation and a reliable connection.',9,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":24,"section":3,"objectiveCodes":["OA3.6"]},"lesson":{"introduction":"Telecommunication services allow offices to exchange voice, documents, images and data across distance. Examples include fixed and mobile telephone services, internet access, messaging, voice mail, video conferencing and data services. A virtual meeting can bring colleagues from different islands together without requiring travel, but its usefulness depends on preparation and a reliable connection.","objectives":["assess the importance of services offered by telecommunication providers"],"sections":[{"title":"How it works","paragraphs":["Compare services against the work. Consider coverage, reliability, bandwidth, speed, cost, technical support, compatibility, security and the needs of users with disabilities. A package that is cheap but unreliable during customer-service hours can damage the business. Cloud services can support shared documents and remote access, but permissions and an agreed version-control procedure remain necessary.","For a conference call or online meeting, check the invitation, connection, microphone, camera and necessary files in advance. Use the correct link and access settings, identify participants and follow meeting etiquette. Share only the intended screen or window. Protect passwords and verify requests for confidential information through an approved route. Have a sensible fallback, such as an authorised telephone number, if the connection fails."]},{"title":"A practical office example","paragraphs":["A Tobago office and a Kingston branch need to review a stock spreadsheet. A video meeting with controlled screen sharing lets them discuss the same figures. The organiser circulates the correct version first, restricts the meeting invitation to participants and arranges a telephone fallback. A faster internet plan alone would not solve an incorrect spreadsheet or an exposed meeting link."]},{"title":"Avoid this mistake","paragraphs":["Do not confuse a provider''s service with a device: a smartphone is equipment, while mobile voice or data access is a service. Technology does not remove the need to verify recipients and protect records."]}],"keyPoints":["Telecommunication services allow offices to exchange voice, documents, images and data across distance.","Compare services against the work.","For a conference call or online meeting, check the invitation, connection, microphone, camera and necessary files in advance."],"summary":"It reduces delays and helps ensure that only the intended material is displayed, protecting both meeting time and confidential information.","check":{"question":"Why should a clerk test screen sharing before a virtual meeting?","answer":"It reduces delays and helps ensure that only the intended material is displayed, protecting both meeting time and confidential information."},"flashcards":[{"id":"OA3.6","front":"Assess the importance of services offered by telecommunication providers.","back":"Voice, data, messaging, internet access and conferencing services support communication across distance. Compare coverage, reliability, speed, cost, support, compatibility, security and accessibility against the work.","objectiveCodes":["OA3.6"]},{"id":"oa-check-10","front":"Why should a clerk test screen sharing before a virtual meeting?","back":"It reduces delays and helps ensure that only the intended material is displayed, protecting both meeting time and confidential information.","objectiveCodes":["OA3.6"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s3-lesson-11','oa-section-3','Receive, sort and dispatch mail and parcels','Incoming mail may arrive by post, courier, hand delivery or electronic means. Follow the office procedure for recording receipt, checking addresses, identifying urgent items, opening authorised mail, date-stamping and sorting it, noting enclosures and routing it promptly. Mail marked personal or confidential should go to the authorised recipient unopened unless a specific approved procedure says otherwise. Treat suspicious packages under the organisation''s safety instructions rather than opening them to investigate.',10,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":24,"section":3,"objectiveCodes":["OA3.7","OA3.8","OA3.9"]},"lesson":{"introduction":"Incoming mail may arrive by post, courier, hand delivery or electronic means. Follow the office procedure for recording receipt, checking addresses, identifying urgent items, opening authorised mail, date-stamping and sorting it, noting enclosures and routing it promptly. Mail marked personal or confidential should go to the authorised recipient unopened unless a specific approved procedure says otherwise. Treat suspicious packages under the organisation''s safety instructions rather than opening them to investigate.","objectives":["describe the services available for dispatching mail","outline procedures for sending and receiving parcels","examine procedures for dealing with incoming and outgoing mail in large and small offices"],"sections":[{"title":"How it works","paragraphs":["Outgoing mail should be checked for the correct addressee, date, signature, enclosures, attachments and return details. Choose a dispatch service by urgency, cost, destination, weight, value, tracking and proof-of-delivery requirements. Ordinary post may suit a routine letter; a tracked or registered service may suit an important original document. A courier can offer speed and collection arrangements. The exact services and conditions should be checked with the provider.","For parcels, pack the contents securely, use cushioning where needed, label the destination and sender clearly and complete the required dispatch or customs information. Record the reference and retain the receipt. On receipt, check the package and accompanying documents, record discrepancies and obtain an acknowledgement where required. A large office may have a mailroom and collection schedule; a small office may combine these duties, but accuracy, custody and confidentiality are still necessary."]},{"title":"Apply the service rules for the destination","paragraphs":["The service name alone does not tell you whether an item is eligible. Jamaica Post announced that, from 1 January 2026, outbound registered mail is limited to documents. Merchandise must use an eligible parcel, EMS or other available service. This is a current dispatch example, not a reason to change the wording or answer context of an older historical question.","Before sending an item, distinguish documents from merchandise and check the destination, contents restrictions, packaging, customs information, tracking and available service. Keep the posting receipt and reference. A delivery estimate is not an unconditional guarantee that customs, weather or an incomplete address cannot delay an item."]},{"title":"A practical office example","paragraphs":["An office sends an original signed agreement to a supplier. Check the signature and enclosures, confirm the address, choose a service with suitable tracking or proof of delivery and record the tracking reference. If an incoming letter says that three certificates are enclosed but only two are present, record the discrepancy and report it before filing the letter as complete."]},{"title":"Avoid this mistake","paragraphs":["Do not put an unopened confidential letter through the ordinary opening routine. A dispatch book records what was sent; it does not by itself prove that the addressee received it."]}],"keyPoints":["Incoming mail may arrive by post, courier, hand delivery or electronic means.","Outgoing mail should be checked for the correct addressee, date, signature, enclosures, attachments and return details.","For parcels, pack the contents securely, use cushioning where needed, label the destination and sender clearly and complete the required dispatch or customs information."],"summary":"It links the dispatch record to the carrier''s service and helps trace the parcel, answer enquiries and investigate a delay or delivery dispute.","check":{"question":"Why should the clerk retain a parcel''s tracking number?","answer":"It links the dispatch record to the carrier''s service and helps trace the parcel, answer enquiries and investigate a delay or delivery dispute."},"flashcards":[{"id":"OA3.7","front":"Describe the services available for dispatching mail.","back":"Choose post, registered or tracked services, courier or electronic dispatch according to urgency, cost, destination, weight, value and proof-of-delivery needs. Verify the actual service conditions with the provider.","objectiveCodes":["OA3.7"]},{"id":"OA3.8","front":"Outline procedures for sending and receiving parcels.","back":"Pack and label securely, check sender and destination, complete required documents, record the reference and retain dispatch evidence. On receipt, check condition and contents and record discrepancies before acknowledging acceptance.","objectiveCodes":["OA3.8"]},{"id":"OA3.9","front":"Examine procedures for dealing with incoming and outgoing mail in large and small offices.","back":"Incoming mail is received, checked, recorded, opened only when authorised, sorted and routed. Outgoing mail is checked for address, signature and enclosures, recorded and sent by a suitable service. Protect confidential items.","objectiveCodes":["OA3.9"]},{"id":"oa-check-11","front":"Why should the clerk retain a parcel''s tracking number?","back":"It links the dispatch record to the carrier''s service and helps trace the parcel, answer enquiries and investigate a delay or delivery dispute.","objectiveCodes":["OA3.7","OA3.8","OA3.9"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s4-lesson-12','oa-section-4','Meeting terms and the different kinds of meetings','A meeting brings people together to exchange information, consult or make decisions. Formal meetings follow established rules and documents; informal meetings are less structured. An Annual General Meeting is held periodically for the organisation''s required annual business; an extraordinary or special meeting deals with business that cannot wait for the usual cycle. Committee, departmental and staff meetings each serve a different group and purpose. Virtual and face-to-face describe how people attend, not whether the business is formal.',11,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":28,"section":4,"objectiveCodes":["OA4.1","OA4.4"]},"lesson":{"introduction":"A meeting brings people together to exchange information, consult or make decisions. Formal meetings follow established rules and documents; informal meetings are less structured. An Annual General Meeting is held periodically for the organisation''s required annual business; an extraordinary or special meeting deals with business that cannot wait for the usual cycle. Committee, departmental and staff meetings each serve a different group and purpose. Virtual and face-to-face describe how people attend, not whether the business is formal.","objectives":["define terms associated with business meetings","differentiate among the various types of meetings"],"sections":[{"title":"How it works","paragraphs":["A notice announces a meeting. The agenda lists its business in the intended order. A quorum is the minimum attendance required under the applicable rules before valid business can be conducted. A motion is a proposal put to the meeting; an amendment proposes a change to it. A resolution is a decision formally adopted. Minutes are the written record of proceedings and decisions. Adjournment pauses or ends the sitting under its rules; it does not erase decisions already made.","Read a meeting scenario by asking who must attend, what must be decided, which rules apply and what records are required. A chairperson keeps the discussion orderly and fair, while members contribute relevant information, consider proposals and vote where entitled. Do not assume that every organisation has the same quorum, voting rights or notice period."]},{"title":"Use the meeting terms precisely","paragraphs":["An ad hoc committee is formed for a particular task, rather than as a permanent committee. Verbatim means word for word; ordinary minutes usually record the essential proceedings and decisions rather than every spoken word. By-laws are the organisation’s internal rules. Check them for the meeting’s notice, quorum and voting arrangements.","A proposal is an idea put forward for consideration; a motion is a formal proposal submitted to the meeting under its procedure. A casting vote is an additional deciding vote available to the chair only when the applicable rules allow it in a tied vote. Do not assume every chair has one. Adjournment moves the meeting to a later time or date under its rules; it is different from adopting the motion being discussed."]},{"title":"A practical office example","paragraphs":["A club''s rules require eight eligible members for a quorum. Only six attend its general meeting. The chairperson must apply the club''s rules for that situation rather than declaring a binding vote merely because everyone present agrees. An informal discussion may still be useful, but it is not a substitute for validly conducting the required formal business."]},{"title":"Avoid this mistake","paragraphs":["Do not confuse an agenda with minutes or a motion with an adopted resolution. A video meeting can be formal and still require a quorum and an accurate record."]}],"keyPoints":["A meeting brings people together to exchange information, consult or make decisions.","A notice announces a meeting.","Read a meeting scenario by asking who must attend, what must be decided, which rules apply and what records are required."],"summary":"A motion is a proposal for consideration. Once a proposal is adopted through the required procedure, the resulting decision is recorded as a resolution.","check":{"question":"What is the difference between a motion and a resolution?","answer":"A motion is a proposal for consideration. Once a proposal is adopted through the required procedure, the resulting decision is recorded as a resolution."},"flashcards":[{"id":"OA4.1","front":"Define terms associated with business meetings.","back":"A notice announces the meeting; an agenda lists its business; a quorum is the required minimum attendance. A motion is a proposal, an amendment changes a proposal, a resolution is adopted business and minutes record the proceedings and decisions.","objectiveCodes":["OA4.1"]},{"id":"OA4.4","front":"Differentiate among the various types of meetings.","back":"Formal meetings follow established rules; informal meetings are less structured. AGMs conduct required annual business, special meetings address particular urgent business, and committees or departments meet for their functions. Virtual describes attendance, not formality.","objectiveCodes":["OA4.4"]},{"id":"oa-check-12","front":"What is the difference between a motion and a resolution?","back":"A motion is a proposal for consideration. Once a proposal is adopted through the required procedure, the resulting decision is recorded as a resolution.","objectiveCodes":["OA4.1","OA4.4"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s4-lesson-13','oa-section-4','Prepare meeting documents and record decisions','A meeting notice identifies the organisation, meeting type, date, time, venue or access link and the authorised person issuing it. The agenda should list business in a clear sequence. A typical formal sequence includes apologies, confirmation of previous minutes, matters arising, reports, new business and arrangements for the next meeting, but the organisation''s own rules take precedence. Circulate documents early enough for members to prepare.',12,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":29,"section":4,"objectiveCodes":["OA4.2","OA4.3"]},"lesson":{"introduction":"A meeting notice identifies the organisation, meeting type, date, time, venue or access link and the authorised person issuing it. The agenda should list business in a clear sequence. A typical formal sequence includes apologies, confirmation of previous minutes, matters arising, reports, new business and arrangements for the next meeting, but the organisation''s own rules take precedence. Circulate documents early enough for members to prepare.","objectives":["prepare documents associated with meetings","discuss the roles and functions of personnel associated with meetings"],"sections":[{"title":"How it works","paragraphs":["The secretary arranges notices and papers, checks attendance records, takes notes and prepares draft minutes. The chairperson manages the meeting, keeps the discussion relevant, puts proposals to the meeting where required and confirms decisions. Members prepare, contribute, observe the rules and carry out agreed tasks. These roles support each other; the secretary should not invent a decision because it seems a sensible conclusion.","Minutes normally identify the meeting, date, place, those present, apologies and the business conducted. Record decisions, motions and voting outcomes where necessary, with responsibility and deadlines for action. Use clear, concise, accurate language. Minutes are not usually a word-for-word transcript or a record of the secretary''s opinion. Follow the procedure for checking, approval, signature, distribution and secure storage."]},{"title":"A practical office example","paragraphs":["The committee agrees that Ms Thomas will obtain three catering quotations by 8 May. A useful minute records that decision, Ms Thomas''s responsibility and the deadline. ''Catering discussed'' is too vague to guide action. If the committee only considers a suggestion without adopting it, do not record it as an instruction to purchase."]},{"title":"Avoid this mistake","paragraphs":["Do not write minutes as a personal account of who sounded convincing. Separate an actual decision from discussion and leave an uncertain fact to be checked rather than guessing."]}],"keyPoints":["A meeting notice identifies the organisation, meeting type, date, time, venue or access link and the authorised person issuing it.","The secretary arranges notices and papers, checks attendance records, takes notes and prepares draft minutes.","Minutes normally identify the meeting, date, place, those present, apologies and the business conducted."],"summary":"It identifies the agreed task, the person responsible and the deadline, so progress can be followed up and reported.","check":{"question":"What makes an action point useful after a meeting?","answer":"It identifies the agreed task, the person responsible and the deadline, so progress can be followed up and reported."},"flashcards":[{"id":"OA4.2","front":"Prepare documents associated with meetings.","back":"Prepare a notice with the meeting identity, date, time, place and authority; an ordered agenda; and accurate minutes recording attendance, business, decisions and actions. Follow checking, approval, circulation and storage procedures.","objectiveCodes":["OA4.2"]},{"id":"OA4.3","front":"Discuss the roles and functions of personnel associated with meetings.","back":"The chairperson manages the proceedings and confirms decisions. The secretary prepares arrangements, documents and minutes. Members prepare, participate, observe the rules and carry out agreed actions.","objectiveCodes":["OA4.3"]},{"id":"oa-check-13","front":"What makes an action point useful after a meeting?","back":"It identifies the agreed task, the person responsible and the deadline, so progress can be followed up and reported.","objectiveCodes":["OA4.2","OA4.3"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s4-lesson-14','oa-section-4','Organise a meeting and follow up its business','Start with the meeting''s purpose and the people whose attendance is needed. Agree a suitable date, time and location; check room capacity, access, seating, equipment, refreshments and likely costs. For a virtual meeting, arrange the platform, link, access controls and technical support. Provide documents and accessibility arrangements in advance and tell participants how to report a problem.',13,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":30,"section":4,"objectiveCodes":["OA4.5","OA4.6","OA4.7"]},"lesson":{"introduction":"Start with the meeting''s purpose and the people whose attendance is needed. Agree a suitable date, time and location; check room capacity, access, seating, equipment, refreshments and likely costs. For a virtual meeting, arrange the platform, link, access controls and technical support. Provide documents and accessibility arrangements in advance and tell participants how to report a problem.","objectives":["organise different types of meetings virtually and face to face","discuss basic legal requirements of Annual General Meetings","outline the follow-up procedures related to decisions made at meetings"],"sections":[{"title":"How it works","paragraphs":["An AGM must follow the organisation''s governing rules and applicable requirements. Check the required notice, eligible participants, quorum, voting procedures, reports, accounts, election arrangements and records. The legal detail can differ by organisation and jurisdiction, so a clerk should use the approved rules and instructions instead of inventing a universal notice period or quorum.","After the meeting, prepare the draft minutes promptly, seek the required checking or approval and circulate the authorised record. Extract action points into a follow-up list with owners and due dates. Send reminders, obtain progress updates and place unresolved matters on the next appropriate agenda. Process authorised expenses, return equipment, file documents securely and update the meeting calendar."]},{"title":"A practical office example","paragraphs":["A branch meeting decides to improve a delivery procedure. The secretary records three actions, assigns an owner to each and sets review dates. Before the next meeting, the secretary asks for progress and circulates the approved information. Repeating the same unresolved item at every meeting without assigning responsibility is not effective follow-up."]},{"title":"Avoid this mistake","paragraphs":["Booking a room is only one part of organising a meeting. A meeting is not complete when participants leave: the decisions need an accurate record and planned action."]}],"keyPoints":["Start with the meeting''s purpose and the people whose attendance is needed.","An AGM must follow the organisation''s governing rules and applicable requirements.","After the meeting, prepare the draft minutes promptly, seek the required checking or approval and circulate the authorised record."],"summary":"The rules determine required notice, eligible participation and valid meeting procedures. Using an ordinary staff-meeting arrangement could make the AGM''s business improperly conducted.","check":{"question":"Why should an organiser check the governing rules before issuing an AGM notice?","answer":"The rules determine required notice, eligible participation and valid meeting procedures. Using an ordinary staff-meeting arrangement could make the AGM''s business improperly conducted."},"flashcards":[{"id":"OA4.5","front":"Organise different types of meetings virtually and face to face.","back":"Confirm purpose, participants, date, notice, location or platform, access, equipment, documents and costs. Prepare participants and test virtual arrangements. Follow up with minutes and an action list.","objectiveCodes":["OA4.5"]},{"id":"OA4.6","front":"Discuss basic legal requirements of Annual General Meetings.","back":"Check the applicable governing rules for notice, eligible participants, quorum, voting, required reports and elections. Requirements differ by organisation and jurisdiction, so do not invent a universal period or attendance figure.","objectiveCodes":["OA4.6"]},{"id":"OA4.7","front":"Outline the follow-up procedures related to decisions made at meetings.","back":"Prepare and check minutes, circulate the authorised record, identify tasks and owners, set deadlines, send reminders, obtain progress reports and bring unresolved actions to the appropriate next meeting.","objectiveCodes":["OA4.7"]},{"id":"oa-check-14","front":"Why should an organiser check the governing rules before issuing an AGM notice?","back":"The rules determine required notice, eligible participation and valid meeting procedures. Using an ordinary staff-meeting arrangement could make the AGM''s business improperly conducted.","objectiveCodes":["OA4.5","OA4.6","OA4.7"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s5-lesson-15','oa-section-5','Plan business travel from the purpose of the visit','Begin with the traveller''s purpose, destination, required arrival date, appointments, budget and preferences allowed by policy. Confirm who authorises travel and spending. Check suitable transport, routes, accommodation, local transfers, communication needs and the time required between each part of the journey. A low fare is not a saving if the traveller arrives after the meeting.',14,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":32,"section":5,"objectiveCodes":["OA5.1","OA5.3"]},"lesson":{"introduction":"Begin with the traveller''s purpose, destination, required arrival date, appointments, budget and preferences allowed by policy. Confirm who authorises travel and spending. Check suitable transport, routes, accommodation, local transfers, communication needs and the time required between each part of the journey. A low fare is not a saving if the traveller arrives after the meeting.","objectives":["outline procedures for making travel arrangements","outline the types of information and services required for travel"],"sections":[{"title":"How it works","paragraphs":["Obtain information from reliable current sources such as the carrier, accommodation provider, official entry-information service or approved travel agent. Check booking conditions, baggage, cancellation terms, connections, accessibility and emergency contact arrangements. Keep records of approvals and confirmations. When information changes, notify the traveller and amend the itinerary and related appointments.","An itinerary places the journey in chronological order. Include relevant dates, departure and arrival locations, local times, flight or service references, accommodation details, appointments, transfers and useful contacts. Distinguish a reservation from a confirmed booking and identify any action still required. Share the itinerary with authorised people and avoid exposing personal documents in a broadly accessible calendar."]},{"title":"A practical office example","paragraphs":["An executive has a 10 a.m. meeting in another island. Compare an early arrival with a flight landing at 9:30. Landing time is not the time the traveller reaches the meeting: allow for arrival procedures, baggage and transfer. If the schedule is unrealistic, propose an earlier flight or travel the previous day within the approved budget."]},{"title":"Avoid this mistake","paragraphs":["Do not plan from departure time alone or treat a booking request as confirmation. Verify each connection and leave realistic time for transfers and preparation."]}],"keyPoints":["Begin with the traveller''s purpose, destination, required arrival date, appointments, budget and preferences allowed by policy.","Obtain information from reliable current sources such as the carrier, accommodation provider, official entry-information service or approved travel agent.","An itinerary places the journey in chronological order."],"summary":"The journey does not end at the airport or terminal. Transfer arrangements and travel time affect whether the traveller can reach the accommodation or appointment on time.","check":{"question":"Why should an itinerary include local transfers?","answer":"The journey does not end at the airport or terminal. Transfer arrangements and travel time affect whether the traveller can reach the accommodation or appointment on time."},"flashcards":[{"id":"OA5.1","front":"Outline procedures for making travel arrangements.","back":"Confirm purpose, required arrival, appointments, approval and budget. Compare routes, transport, accommodation, transfers and booking conditions; obtain confirmations and prepare a chronological itinerary.","objectiveCodes":["OA5.1"]},{"id":"OA5.3","front":"Outline the types of information and services required for travel.","back":"Check current carrier and official requirements, routes, schedules, accommodation, transfers, accessibility, communication and emergency contacts. Keep authorised booking references and confirmations available and secure.","objectiveCodes":["OA5.3"]},{"id":"oa-check-15","front":"Why should an itinerary include local transfers?","back":"The journey does not end at the airport or terminal. Transfer arrangements and travel time affect whether the traveller can reach the accommodation or appointment on time.","objectiveCodes":["OA5.1","OA5.3"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s5-lesson-16','oa-section-5','Travel documents and what each document proves','A passport establishes identity and nationality for international travel. A visa, where required, indicates permission under the destination''s rules; it is not the same document as a passport or a transport ticket. A ticket or electronic booking record identifies the travel service, while a boarding pass is issued for boarding a particular service. Check the information supplied by the relevant authority and carrier for the actual journey.',15,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":33,"section":5,"objectiveCodes":["OA5.2"]},"lesson":{"introduction":"A passport establishes identity and nationality for international travel. A visa, where required, indicates permission under the destination''s rules; it is not the same document as a passport or a transport ticket. A ticket or electronic booking record identifies the travel service, while a boarding pass is issued for boarding a particular service. Check the information supplied by the relevant authority and carrier for the actual journey.","objectives":["discuss the importance of various travel documents"],"sections":[{"title":"How it works","paragraphs":["Other relevant documents may include travel insurance, health documentation, an itinerary, accommodation confirmation, an authorisation letter and documents for carrying business equipment or samples. Travel insurance can cover specified risks under its conditions; it is not a guarantee that every loss will be paid. Keep important reference numbers and emergency contacts accessible while protecting the originals and sensitive personal details.","Before travel, verify names against identity documents and check validity, dates, destinations and booking details. Make secure copies where policy allows and explain where the traveller can access them. Entry and health requirements can change; use current official information instead of relying on a colleague''s experience from a previous year."]},{"title":"Read the purpose of a permit or health certificate","paragraphs":["A travel permit or entry permit is an authorisation issued under the relevant authority’s rules for a stated person, journey or purpose. The terms and conditions vary by territory, so check the document rather than treating it as another name for a passport. A passport identifies the traveller; an entry authorisation addresses permission under the destination’s rules. Holding a visa does not remove the remaining entry checks.","A health certificate provides specified health evidence when it is required, for example an accepted vaccination record for a particular destination or route. It is different from travel insurance, which addresses risks covered by a policy. A clerk should confirm the actual requirement and its validity with the appropriate official source before arranging the journey."]},{"title":"A practical office example","paragraphs":["A reservation is made under ''M. Brown'', but the traveller''s official identity document shows a different full name. Ask the carrier or booking service to confirm the required correction before departure. Do not assume that an itinerary proves identity or that a valid passport removes every other entry requirement."]},{"title":"Avoid this mistake","paragraphs":["A visa is not a ticket, a ticket is not a boarding pass and a hotel booking is not proof of permission to enter a country. State the purpose of each document clearly."]}],"keyPoints":["A passport establishes identity and nationality for international travel.","Other relevant documents may include travel insurance, health documentation, an itinerary, accommodation confirmation, an authorisation letter and documents for carrying business equipment or samples.","Before travel, verify names against identity documents and check validity, dates, destinations and booking details."],"summary":"The booking details need to match the identification required by the carrier and relevant authorities. An error can cause delays, extra charges or difficulty travelling.","check":{"question":"Why should the clerk check the traveller''s name before confirming a booking?","answer":"The booking details need to match the identification required by the carrier and relevant authorities. An error can cause delays, extra charges or difficulty travelling."},"flashcards":[{"id":"OA5.2","front":"Discuss the importance of various travel documents.","back":"A passport establishes identity and nationality; a visa concerns permission under the relevant entry rules; a ticket records transport; a boarding pass permits boarding. Insurance, confirmations and other required documents have separate purposes.","objectiveCodes":["OA5.2"]},{"id":"oa-check-16","front":"Why should the clerk check the traveller''s name before confirming a booking?","back":"The booking details need to match the identification required by the carrier and relevant authorities. An error can cause delays, extra charges or difficulty travelling.","objectiveCodes":["OA5.2"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s5-lesson-17','oa-section-5','Time zones, travel money and a workable schedule','Places can use different local times. Read the time zone for each departure, arrival and appointment, and take account of the date as well as the hour. If a destination is one hour ahead, 10 a.m. at the origin is 11 a.m. there. A flight duration cannot be calculated reliably by subtracting two clock readings from different zones without first putting them on a common time basis.',16,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":33,"section":5,"objectiveCodes":["OA5.4","OA5.5"]},"lesson":{"introduction":"Places can use different local times. Read the time zone for each departure, arrival and appointment, and take account of the date as well as the hour. If a destination is one hour ahead, 10 a.m. at the origin is 11 a.m. there. A flight duration cannot be calculated reliably by subtracting two clock readings from different zones without first putting them on a common time basis.","objectives":["explain the importance of time zones","determine monetary instruments for use during travel"],"sections":[{"title":"How it works","paragraphs":["Use the offset supplied in an examination question. For real bookings, verify the current local time and any seasonal clock changes. When scheduling a virtual meeting, communicate the date and the time in each participant''s location or specify an unambiguous time zone. Check whether a journey crosses midnight and changes the arrival date.","Travel payments may use cash, debit or credit cards, bank transfers, prepaid cards and other services accepted at the destination. Compare acceptance, access to funds, charges, exchange rate, security, proof of payment and the organisation''s policy. A quoted exchange rate needs a clear direction: at US$1 = J$150, US$80 is J$12,000 before any stated fee. Keep receipts and reconcile an authorised travel advance after the visit."]},{"title":"Compare monetary instruments for a business trip","paragraphs":["Cash is immediately usable where that currency is accepted, but loss or theft can be difficult to remedy. A debit card usually pays from an available account balance; a credit card uses an agreed credit facility and is repaid under its terms. Check acceptance, transaction charges and the organisation’s policy before selecting either. Mobile currency or wallet services can make eligible payments through a device, but require the appropriate service, access and recipient acceptance.","A bank draft is a bank-issued payment instrument obtained for a specified payment. A letter of credit is a bank’s undertaking to pay under stated conditions, commonly involving required documents; it is not the same as a credit card or a general promise that the traveller has money. Select the instrument for the actual payment, security and acceptance requirements. Foreign-exchange rates and charges must be taken from the exercise or a current authorised source."]},{"title":"A practical office example","paragraphs":["A flight leaves at 08:00 from a place using UTC−5 and takes three hours. The destination uses UTC−4. Departure is 13:00 UTC; arrival is 16:00 UTC, or 12:00 at the destination. Use the given offsets in this exercise rather than assuming the aircraft arrives at 11:00 local time."]},{"title":"Avoid this mistake","paragraphs":["Do not ignore the arrival date or reverse the exchange-rate calculation. Distinguish the rate quoted in a question from a current market rate, which must be checked for a real transaction."]}],"keyPoints":["Places can use different local times.","Use the offset supplied in an examination question.","Travel payments may use cash, debit or credit cards, bank transfers, prepaid cards and other services accepted at the destination."],"summary":"Multiply 40 by 150: J$6,000. Any separately stated conversion charge must then be included according to the question.","check":{"question":"At US$1 = J$150, how many Jamaican dollars are needed for US$40 before fees?","answer":"Multiply 40 by 150: J$6,000. Any separately stated conversion charge must then be included according to the question."},"flashcards":[{"id":"OA5.4","front":"Explain the importance of time zones.","back":"Convert times to a common reference before comparing them. Use the correct local time and date for each location, including stated offsets and any verified seasonal change. A clock difference alone is not flight duration.","objectiveCodes":["OA5.4"]},{"id":"OA5.5","front":"Determine monetary instruments for use during travel.","back":"Compare cash, cards, transfers and other accepted services for access, cost, exchange direction, security, proof and policy. Use the rate and fees stated in an exercise; verify current terms for an actual transaction.","objectiveCodes":["OA5.5"]},{"id":"oa-check-17","front":"At US$1 = J$150, how many Jamaican dollars are needed for US$40 before fees?","back":"Multiply 40 by 150: J$6,000. Any separately stated conversion charge must then be included according to the question.","objectiveCodes":["OA5.4","OA5.5"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s6-lesson-18','oa-section-6','Records that can be found, trusted and protected','A record is evidence of a transaction, decision or activity. It may be a letter, invoice, employee record, email, image or database entry. Records management controls the record from creation and use through storage, retention and authorised disposal. The records clerk receives and classifies material, indexes and files it, retrieves it when authorised, tracks its movement and helps protect it from loss or unauthorised access.',17,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":35,"section":6,"objectiveCodes":["OA6.1","OA6.2"]},"lesson":{"introduction":"A record is evidence of a transaction, decision or activity. It may be a letter, invoice, employee record, email, image or database entry. Records management controls the record from creation and use through storage, retention and authorised disposal. The records clerk receives and classifies material, indexes and files it, retrieves it when authorised, tracks its movement and helps protect it from loss or unauthorised access.","objectives":["describe the duties of a records and information management clerk","describe the characteristics of a records and information management system"],"sections":[{"title":"How it works","paragraphs":["A useful system is accurate, accessible to authorised users, economical, secure, sufficiently flexible and simple enough for staff to follow consistently. Accessibility does not mean that everyone can open every file. The right person must be able to locate the right version within a reasonable time. A fast search of badly named, inaccurate files is still a poor records system.","Agree naming conventions, responsibilities, access levels and a procedure for checking completeness. Record key facts consistently: a customer number should not change spelling from one document to the next. Keep an audit trail where required so the organisation can establish who accessed or changed a record. Protect physical files against fire, water and theft, and electronic records against unauthorised access, alteration and loss."]},{"title":"A practical office example","paragraphs":["A customer asks why an order was delayed. The clerk retrieves the original order, the approved change and the dispatch record using the same order reference. These records let the business establish what was requested and agreed. A folder containing only the latest unsourced email would not provide the same evidence."]},{"title":"Avoid this mistake","paragraphs":["Do not confuse records management with simply putting old papers in cupboards. A reliable system also controls creation, access, versions, movement and disposal."]}],"keyPoints":["A record is evidence of a transaction, decision or activity.","A useful system is accurate, accessible to authorised users, economical, secure, sufficiently flexible and simple enough for staff to follow consistently.","Agree naming conventions, responsibilities, access levels and a procedure for checking completeness."],"summary":"A consistent reference links the documents to the same matter and makes accurate retrieval, checking and follow-up easier.","check":{"question":"Why should a file reference be used consistently across related documents?","answer":"A consistent reference links the documents to the same matter and makes accurate retrieval, checking and follow-up easier."},"flashcards":[{"id":"OA6.1","front":"Describe the duties of a records and information management clerk.","back":"The clerk classifies, indexes, files and retrieves records, tracks movement, maintains authorised access and assists with retention and secure disposal. Records provide evidence of transactions and decisions.","objectiveCodes":["OA6.1"]},{"id":"OA6.2","front":"Describe the characteristics of a records and information management system.","back":"A good system is accurate, secure, economical, consistent, flexible and accessible to authorised users. It supports timely retrieval of the right record and version without exposing it to unauthorised people.","objectiveCodes":["OA6.2"]},{"id":"oa-check-18","front":"Why should a file reference be used consistently across related documents?","back":"A consistent reference links the documents to the same matter and makes accurate retrieval, checking and follow-up easier.","objectiveCodes":["OA6.1","OA6.2"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s6-lesson-19','oa-section-6','Classify, index, file and retrieve records','Alphabetical filing arranges indexed names in letter order. Compare the surname first for personal names, then the given names if surnames match. Numerical filing arranges assigned numbers and normally needs an index linking names to numbers. Subject filing groups records by topic, geographical filing by location and chronological filing by date. Alphanumeric systems combine letters and numbers. Choose according to the type of information and how staff will search for it.',18,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":36,"section":6,"objectiveCodes":["OA6.3","OA6.4"]},"lesson":{"introduction":"Alphabetical filing arranges indexed names in letter order. Compare the surname first for personal names, then the given names if surnames match. Numerical filing arranges assigned numbers and normally needs an index linking names to numbers. Subject filing groups records by topic, geographical filing by location and chronological filing by date. Alphanumeric systems combine letters and numbers. Choose according to the type of information and how staff will search for it.","objectives":["analyse the different types of records and information management systems","maintain a record and information management system"],"sections":[{"title":"How it works","paragraphs":["Before filing, check that the document has been dealt with and is authorised for filing, classify its subject or owner, select the correct index heading and reference, and put it in the right location. Cross-reference when users may reasonably search under another heading. Follow a documented rule for company names, prefixes and unusual names rather than making a different choice each time.","When a paper file is removed, use the approved out-card, tracer or movement register to record who has it, where it has gone and when it should return. For electronic records, use agreed folder structures, metadata and version control. Search results need checking: two files with similar names may relate to different customers. Return material promptly and keep the filing area orderly."]},{"title":"A practical office example","paragraphs":["Six records are indexed Brown, Marcia; Brown, Mark; Brown, Michael; Browne, Martin; Campbell, Alan; Clarke, Denise. Compare surnames letter by letter: Brown precedes Browne. For the three Brown records, Marcia precedes Mark, which precedes Michael. Use the filing practice to work through the order rather than relying on the first letter alone."]},{"title":"Avoid this mistake","paragraphs":["A numerical system is not automatically searchable by customer name; it needs an index. Do not remove a paper file without a movement record or silently overwrite an electronic version needed as evidence."]}],"keyPoints":["Alphabetical filing arranges indexed names in letter order.","Before filing, check that the document has been dealt with and is authorised for filing, classify its subject or owner, select the correct index heading and reference, and put it in the right location.","When a paper file is removed, use the approved out-card, tracer or movement register to record who has it, where it has gone and when it should return."],"summary":"It shows that the file is temporarily elsewhere and records the person or location to contact, reducing lost files and unnecessary searching.","check":{"question":"Why is an out-card left when a file is borrowed?","answer":"It shows that the file is temporarily elsewhere and records the person or location to contact, reducing lost files and unnecessary searching."},"flashcards":[{"id":"OA6.3","front":"Analyse the different types of records and information management systems.","back":"Alphabetical systems use indexed names, numerical systems use assigned numbers and an index, subject systems use topics, geographical systems use locations and chronological systems use dates. Choose for the expected retrieval need.","objectiveCodes":["OA6.3"]},{"id":"OA6.4","front":"Maintain a record and information management system.","back":"Check and classify the record, choose a consistent index and reference, file correctly, cross-reference where needed and record movement. Use version control and return borrowed records promptly.","objectiveCodes":["OA6.4"]},{"id":"oa-check-19","front":"Why is an out-card left when a file is borrowed?","back":"It shows that the file is temporarily elsewhere and records the person or location to contact, reducing lost files and unnecessary searching.","objectiveCodes":["OA6.3","OA6.4"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s6-lesson-20','oa-section-6','Inactive records, retention, access and secure disposal','An inactive file is no longer needed frequently for current work. It may still be required for reference, legal obligations or historical value. Review records under an authorised retention schedule: keep them in active storage while in frequent use, transfer or archive them when appropriate, and dispose of them only when authorised. Age alone is not sufficient reason to destroy a file.',19,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":37,"section":6,"objectiveCodes":["OA6.5","OA6.6"]},"lesson":{"introduction":"An inactive file is no longer needed frequently for current work. It may still be required for reference, legal obligations or historical value. Review records under an authorised retention schedule: keep them in active storage while in frequent use, transfer or archive them when appropriate, and dispose of them only when authorised. Age alone is not sufficient reason to destroy a file.","objectives":["outline the methods and procedures for dealing with inactive files","describe the main legal stipulations governing access to and retention of documents"],"sections":[{"title":"How it works","paragraphs":["Retention and access requirements vary by record, organisation and jurisdiction. A clerk should use the applicable policy and instructions, especially for employee, financial, health, customer and legal records. A record connected with an unresolved dispute or an official preservation instruction must not be destroyed merely because a routine retention date has arrived. Seek guidance rather than guessing a retention period.","Protect personal information by collecting only what is needed, using it for authorised purposes, limiting access, keeping it accurate and arranging secure disposal. Paper records may need shredding or another approved destruction service; electronic records may require secure deletion or media sanitisation rather than merely moving a file to the recycle bin. Keep the required disposal authorisation and record. An archive is controlled storage, not an unattended pile of unwanted boxes."]},{"title":"Distinguish archiving, microfilming and backup","paragraphs":["Microfilming records reduced photographic images of documents on film, which need suitable equipment to read. Microfiche holds reduced images on a flat sheet. These methods can reduce storage space for some inactive records, but indexing, legibility, preservation conditions and a way to retrieve the information remain necessary. A digitised scan is a different storage format.","Archiving transfers records worth retaining to controlled long-term storage. A backup is a recovery copy of electronic information; an off-site or cloud backup can reduce the risk of losing both working and recovery copies in the same incident. A backup does not replace a retention schedule, and moving a file to cloud storage does not make uncontrolled access acceptable."]},{"title":"Access to a record is not permission to use it in every way","paragraphs":["A right of access may be limited to the person concerned or a properly authorised requester. Freedom-of-information arrangements concern access under the applicable law and can include exemptions; they do not make every personnel, medical or commercial file public. Check the requester’s identity, authority and the organisation’s approved process before releasing a record.","Copyright controls certain uses of protected work, including copying and publication, subject to licences and legal exceptions. Finding a photograph or report online is not automatic permission to reproduce it. Breach of confidence concerns unauthorised use or disclosure of confidential information. Publishing a false statement that harms reputation can raise a defamation issue. Secrecy provisions and record-retention requirements may add duties for particular work.","For a Jamaican example, the Office of the Information Commissioner explains purpose, data minimisation, accuracy, storage limits, access rights and security under the Data Protection Act, 2020. Its guidance does not prescribe one universal retention period for every file. Record the applicable rule, keep the required authorisation and ask the responsible officer about an uncertain request rather than inventing a rule."]},{"title":"A practical office example","paragraphs":["A former employee''s file has reached the routine review date, but a matter involving that employment is still unresolved. Refer the file for guidance and preserve it under the applicable instruction. Do not shred it automatically. When records are eventually authorised for disposal, protect the contents during transport and destruction as well as while they are in the office."]},{"title":"Avoid this mistake","paragraphs":["Inactive does not mean worthless. Deleting a shortcut does not delete the underlying electronic record, and an ordinary rubbish bin is unsuitable for confidential documents."]}],"keyPoints":["An inactive file is no longer needed frequently for current work.","Retention and access requirements vary by record, organisation and jurisdiction.","Protect personal information by collecting only what is needed, using it for authorised purposes, limiting access, keeping it accurate and arranging secure disposal."],"summary":"Check the retention schedule, any outstanding preservation requirement and the required authorisation. Use an approved secure disposal method and retain the disposal record where required.","check":{"question":"What should happen before an inactive file is destroyed?","answer":"Check the retention schedule, any outstanding preservation requirement and the required authorisation. Use an approved secure disposal method and retain the disposal record where required."},"flashcards":[{"id":"OA6.5","front":"Outline the methods and procedures for dealing with inactive files.","back":"Review inactive files under an authorised retention schedule, transfer or archive those still needed and securely dispose of only those authorised. Check unresolved matters or preservation instructions before destruction.","objectiveCodes":["OA6.5"]},{"id":"OA6.6","front":"Describe the main legal stipulations governing access to and retention of documents.","back":"Apply the relevant access, confidentiality and retention requirements for the record and jurisdiction. Restrict use to authorised purposes and people, preserve required evidence and follow approved disposal instructions.","objectiveCodes":["OA6.6"]},{"id":"oa-check-20","front":"What should happen before an inactive file is destroyed?","back":"Check the retention schedule, any outstanding preservation requirement and the required authorisation. Use an approved secure disposal method and retain the disposal record where required.","objectiveCodes":["OA6.5","OA6.6"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s6-lesson-21','oa-section-6','Records equipment and centralised or departmental systems','Manual resources include filing cabinets, shelves, folders, guides, indexes, labels, out-cards and secure storage. Electronic resources include computers, scanners, document-management software, databases, storage devices and backup systems. Select resources for the volume, format, security and retrieval needs of the records. Scanning creates an electronic copy; it does not automatically verify the text or authorise disposal of the original.',20,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":38,"section":6,"objectiveCodes":["OA6.7","OA6.8"]},"lesson":{"introduction":"Manual resources include filing cabinets, shelves, folders, guides, indexes, labels, out-cards and secure storage. Electronic resources include computers, scanners, document-management software, databases, storage devices and backup systems. Select resources for the volume, format, security and retrieval needs of the records. Scanning creates an electronic copy; it does not automatically verify the text or authorise disposal of the original.","objectives":["discuss the use of manual and electronic resources required for records and information management","differentiate between centralised and decentralised records and information management systems"],"sections":[{"title":"How it works","paragraphs":["Centralised filing places records under one common service. It can improve standardisation, specialist control and use of space, but staff may need to wait for retrieval and access across locations must be planned. Decentralised filing keeps records in the departments that use them. It can speed local access and suit specialist work, but may duplicate resources and produce inconsistent procedures. A mixed system can centralise some records while leaving active departmental records locally controlled.","Electronic records need access controls, backups, recovery procedures, appropriate search fields and staff training. A backup is a recovery copy; it is not a substitute for an organised working file system. Test whether records can be restored. Apply the same confidentiality principles to shared drives, cloud services and remote working as to a locked filing cabinet."]},{"title":"A practical office example","paragraphs":["A hotel keeps routine supplier invoices in a central accounts records service but gives authorised HR staff separate control of personnel files. Both use an agreed retention and naming policy. This combines efficient common procedures with appropriate access restrictions rather than choosing a single arrangement for every kind of record."]},{"title":"Avoid this mistake","paragraphs":["Do not assume that an electronic system is safe merely because it has a password or that centralisation gives every employee access to all records."]}],"keyPoints":["Manual resources include filing cabinets, shelves, folders, guides, indexes, labels, out-cards and secure storage.","Centralised filing places records under one common service.","Electronic records need access controls, backups, recovery procedures, appropriate search fields and staff training."],"summary":"Records can be retrieved quickly by the department using them, but different departments may duplicate records or apply inconsistent naming and retention procedures unless standards are coordinated.","check":{"question":"Give one advantage and one risk of decentralised filing.","answer":"Records can be retrieved quickly by the department using them, but different departments may duplicate records or apply inconsistent naming and retention procedures unless standards are coordinated."},"flashcards":[{"id":"OA6.7","front":"Discuss the use of manual and electronic resources required for records and information management.","back":"Manual systems use cabinets, folders, guides, indexes and tracers. Electronic systems use computers, scanners, databases, document software and backup resources. Both require accurate input, access controls and trained users.","objectiveCodes":["OA6.7"]},{"id":"OA6.8","front":"Differentiate between centralised and decentralised records and information management systems.","back":"Centralised systems combine records under common control, improving consistency but requiring retrieval arrangements. Decentralised systems keep records near users, helping local access but risking duplication and inconsistent procedures.","objectiveCodes":["OA6.8"]},{"id":"oa-check-21","front":"Give one advantage and one risk of decentralised filing.","back":"Records can be retrieved quickly by the department using them, but different departments may duplicate records or apply inconsistent naming and retention procedures unless standards are coordinated.","objectiveCodes":["OA6.7","OA6.8"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s7-lesson-22','oa-section-7','The human resources office and its confidential records','Human Resource Management supports the people needed for the organisation''s work. Its functions include workforce planning, recruitment and selection, induction, training and development, employee records, attendance, welfare, performance procedures and employee relations. Some activities are shared with line managers and payroll. HR should help the organisation meet its staffing needs while treating employees fairly and consistently.',21,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":41,"section":7,"objectiveCodes":["OA7.1","OA7.2"]},"lesson":{"introduction":"Human Resource Management supports the people needed for the organisation''s work. Its functions include workforce planning, recruitment and selection, induction, training and development, employee records, attendance, welfare, performance procedures and employee relations. Some activities are shared with line managers and payroll. HR should help the organisation meet its staffing needs while treating employees fairly and consistently.","objectives":["describe the functions and importance of the Human Resource Management office","examine the duties and attributes of a clerk in the Human Resource Management office"],"sections":[{"title":"How it works","paragraphs":["An HR clerk may organise applications and interviews, maintain authorised personnel records, prepare routine correspondence, record leave and attendance and help arrange training. Accuracy and discretion matter because errors can affect pay, leave, opportunities and trust. The clerk should be organised, courteous, impartial and able to handle sensitive information without discussing it casually.","Follow a clear procedure when information changes. Verify the authority for the change, update the correct employee record, retain the necessary supporting evidence and notify the appropriate office through an approved channel. Do not promise a job, promotion or leave approval unless authorised. Direct questions about policy or personal entitlements to the responsible person."]},{"title":"A practical office example","paragraphs":["A supervisor sends an approved change to an employee''s work schedule. The HR clerk confirms the employee reference and effective date, updates the authorised record and informs payroll if necessary. The clerk does not change the pay rate simply because the schedule changed; the pay instruction needs its own authority."]},{"title":"Avoid this mistake","paragraphs":["An HR clerk supports the process but does not automatically have authority to make employment decisions. Confidentiality applies to unsuccessful applicants as well as current employees."]}],"keyPoints":["Human Resource Management supports the people needed for the organisation''s work.","An HR clerk may organise applications and interviews, maintain authorised personnel records, prepare routine correspondence, record leave and attendance and help arrange training.","Follow a clear procedure when information changes."],"summary":"Payroll needs the correct effective date and authorised details to calculate pay properly. An incomplete or late notification can produce an incorrect payment.","check":{"question":"Why must HR communicate an approved employment change accurately to payroll?","answer":"Payroll needs the correct effective date and authorised details to calculate pay properly. An incomplete or late notification can produce an incorrect payment."},"flashcards":[{"id":"OA7.1","front":"Describe the functions and importance of the Human Resource Management office.","back":"HR supports staffing, recruitment, selection, induction, training, records, attendance, welfare and employee relations. It coordinates with managers and payroll while supporting fair and effective treatment of employees.","objectiveCodes":["OA7.1"]},{"id":"OA7.2","front":"Examine the duties and attributes of a clerk in the Human Resource Management office.","back":"The HR clerk maintains authorised personnel data, organises applications and interviews, prepares correspondence and supports leave and training records. Accuracy, discretion, impartiality and organisation are vital.","objectiveCodes":["OA7.2"]},{"id":"oa-check-22","front":"Why must HR communicate an approved employment change accurately to payroll?","back":"Payroll needs the correct effective date and authorised details to calculate pay properly. An incomplete or late notification can produce an incorrect payment.","objectiveCodes":["OA7.1","OA7.2"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s7-lesson-23','oa-section-7','Find and evaluate employment opportunities','Vacancies can be advertised through an organisation''s website, newspapers, recruitment agencies, employment services, professional associations, school or college careers services and suitable online job platforms. Personal contacts can alert someone to a vacancy, but the applicant should verify the employer and the application procedure. Be cautious about requests for fees or unnecessary personal information.',22,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":43,"section":7,"objectiveCodes":["OA7.3","OA7.4"]},"lesson":{"introduction":"Vacancies can be advertised through an organisation''s website, newspapers, recruitment agencies, employment services, professional associations, school or college careers services and suitable online job platforms. Personal contacts can alert someone to a vacancy, but the applicant should verify the employer and the application procedure. Be cautious about requests for fees or unnecessary personal information.","objectives":["identify sources of information on job opportunities","outline factors to be considered when seeking employment"],"sections":[{"title":"How it works","paragraphs":["Read the advertisement carefully. Separate essential requirements from desirable qualities and note the job title, main duties, qualification or experience requirements, location, working hours, closing date and method of application. Consider pay, benefits, travel costs, development opportunities, working conditions, accessibility and whether the role matches your interests and abilities. A high stated salary may not compensate for impractical hours or excessive travel costs.","Research the organisation using reliable information. Tailor the application to the role and use evidence of relevant skills from school, work experience, volunteering or other responsibilities. Keep a record of applications, deadlines and responses. Apply through the verified channel and follow the requested document and file-naming instructions."]},{"title":"A practical office example","paragraphs":["Two entry-level positions have similar pay. One requires a costly two-hour commute and evening work; the other offers relevant training near home. Compare the full conditions and your circumstances instead of choosing from the salary line alone. In both cases, verify the advertisement on the employer''s official channel before sending an application."]},{"title":"Avoid this mistake","paragraphs":["Do not apply with the same unedited letter for every vacancy or ignore the closing date. Avoid inventing qualifications to meet a requirement."]}],"keyPoints":["Vacancies can be advertised through an organisation''s website, newspapers, recruitment agencies, employment services, professional associations, school or college careers services and suitable online job platforms.","Read the advertisement carefully.","Research the organisation using reliable information."],"summary":"Verify the employer and recruitment channel, understand which documents are genuinely required and use the authorised application procedure.","check":{"question":"What should an applicant check before sending personal documents to an online vacancy?","answer":"Verify the employer and recruitment channel, understand which documents are genuinely required and use the authorised application procedure."},"flashcards":[{"id":"OA7.3","front":"Identify sources of information on job opportunities.","back":"Look at verified employer sites, newspapers, recruitment agencies, employment services, careers offices and relevant professional channels. Check that the vacancy and application route are genuine.","objectiveCodes":["OA7.3"]},{"id":"OA7.4","front":"Outline factors to be considered when seeking employment.","back":"Compare the duties, requirements, pay, hours, conditions, location, travel costs, training and prospects with your abilities and circumstances. Read the closing date and application instructions carefully.","objectiveCodes":["OA7.4"]},{"id":"oa-check-23","front":"What should an applicant check before sending personal documents to an online vacancy?","back":"Verify the employer and recruitment channel, understand which documents are genuinely required and use the authorised application procedure.","objectiveCodes":["OA7.3","OA7.4"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s7-lesson-24','oa-section-7','Prepare job applications and employment correspondence','An application letter identifies the vacancy and source, explains the applicant''s interest and gives relevant evidence of suitability. Use a professional business-letter layout, an appropriate salutation and closing and accurate contact details. A curriculum vitae or résumé summarises education, skills, experience and other relevant evidence in a clear order. An application form requests the employer''s required information in a standard format; follow its instructions and complete each applicable field accurately.',23,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":43,"section":7,"objectiveCodes":["OA7.5","OA7.6"]},"lesson":{"introduction":"An application letter identifies the vacancy and source, explains the applicant''s interest and gives relevant evidence of suitability. Use a professional business-letter layout, an appropriate salutation and closing and accurate contact details. A curriculum vitae or résumé summarises education, skills, experience and other relevant evidence in a clear order. An application form requests the employer''s required information in a standard format; follow its instructions and complete each applicable field accurately.","objectives":["prepare documents required for employment","prepare other types of documents"],"sections":[{"title":"How it works","paragraphs":["Connect claims to evidence. Instead of writing only ''I am organised'', describe maintaining a club register, preparing a meeting agenda or meeting deadlines on a project. Proofread names, dates, contact details, spelling and attachments. Obtain permission before naming a referee and provide accurate details. Do not include sensitive information that is not required.","Employment correspondence may include an acceptance, acknowledgement, request, transfer application, leave application, resignation or other routine communication. State the purpose clearly, refer to relevant dates and documents and explain the action requested. Keep a respectful tone even when declining an offer or resigning. Follow the applicable agreement and procedure rather than inventing a universal notice period."]},{"title":"A practical office example","paragraphs":["A vacancy asks for a letter, a résumé and the reference OA-17 in the email subject. Prepare the two documents, name the files clearly, check that both are attached and place OA-17 in the subject. A well-written letter sent without the requested reference or attachment may be harder to process correctly."]},{"title":"Avoid this mistake","paragraphs":["Do not confuse an application letter with a résumé: they support each other but serve different purposes. Never fabricate experience or provide a referee''s details without permission."]}],"keyPoints":["An application letter identifies the vacancy and source, explains the applicant''s interest and gives relevant evidence of suitability.","Connect claims to evidence.","Employment correspondence may include an acceptance, acknowledgement, request, transfer application, leave application, resignation or other routine communication."],"summary":"Give a relevant truthful example, such as organising club records, scheduling an event or coordinating project deadlines, and explain the responsibility carried out.","check":{"question":"How can a school leaver support a claim of good organisational skills?","answer":"Give a relevant truthful example, such as organising club records, scheduling an event or coordinating project deadlines, and explain the responsibility carried out."},"flashcards":[{"id":"OA7.5","front":"Prepare documents required for employment.","back":"Prepare a tailored application letter, truthful résumé or CV, requested application form and attachments. Provide relevant evidence, accurate contacts and authorised referee details, and proofread everything.","objectiveCodes":["OA7.5"]},{"id":"OA7.6","front":"Prepare other types of documents.","back":"Employment correspondence may include acceptance, acknowledgement, leave or transfer requests and resignation. State the purpose, relevant dates and requested action clearly and follow the applicable procedure.","objectiveCodes":["OA7.6"]},{"id":"oa-check-24","front":"How can a school leaver support a claim of good organisational skills?","back":"Give a relevant truthful example, such as organising club records, scheduling an event or coordinating project deadlines, and explain the responsibility carried out.","objectiveCodes":["OA7.5","OA7.6"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s7-lesson-25','oa-section-7','Prepare for an interview and enter the workplace','Prepare for an interview by researching the employer and role, reviewing your application and gathering truthful examples of relevant skills. Confirm the date, time, location or video link, route and required documents. Choose suitable professional dress and allow time for delays. For a virtual interview, check sound, connection, background and access to the correct link.',24,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":44,"section":7,"objectiveCodes":["OA7.7","OA7.8"]},"lesson":{"introduction":"Prepare for an interview by researching the employer and role, reviewing your application and gathering truthful examples of relevant skills. Confirm the date, time, location or video link, route and required documents. Choose suitable professional dress and allow time for delays. For a virtual interview, check sound, connection, background and access to the correct link.","objectives":["explain factors to be considered when preparing for a job interview","demonstrate knowledge of the requirements of the work environment"],"sections":[{"title":"How it works","paragraphs":["Listen to each question, answer clearly and relate examples to the role. If a question is unclear, ask for clarification rather than answering a different one. Be honest about what you know and show willingness to learn. Prepare sensible questions about duties, training or the work. Keep your telephone from interrupting and thank the panel courteously.","After appointment, induction introduces the employee to the organisation, people, duties, procedures, safety arrangements and expected conduct. Learn attendance and reporting rules, use of equipment, confidentiality, customer service, emergency procedures and the route for asking questions. Training develops knowledge and skills; evaluation helps identify progress and further support. Being new is a reason to clarify an instruction, not to ignore it."]},{"title":"A practical office example","paragraphs":["During an interview, an applicant is asked about handling a deadline. A useful answer describes the task, the actions taken and the result rather than merely saying ''I work well under pressure''. On starting work, the new employee checks how urgent tasks should be prioritised and who must approve changes."]},{"title":"Avoid this mistake","paragraphs":["Do not memorise a false story or arrive without knowing the role. A confident answer can still be inaccurate; honesty and relevant evidence are more useful than exaggeration."]}],"keyPoints":["Prepare for an interview by researching the employer and role, reviewing your application and gathering truthful examples of relevant skills.","Listen to each question, answer clearly and relate examples to the role.","After appointment, induction introduces the employee to the organisation, people, duties, procedures, safety arrangements and expected conduct."],"summary":"It helps a new employee understand the organisation, duties, colleagues, procedures, safety requirements and expected conduct so they can begin working effectively.","check":{"question":"What is the purpose of induction?","answer":"It helps a new employee understand the organisation, duties, colleagues, procedures, safety requirements and expected conduct so they can begin working effectively."},"flashcards":[{"id":"OA7.7","front":"Explain factors to be considered when preparing for a job interview.","back":"Research the role and organisation, review your application, prepare truthful examples and documents and confirm time, location or link. Plan dress and travel; test technology for a virtual interview.","objectiveCodes":["OA7.7"]},{"id":"OA7.8","front":"Demonstrate knowledge of the requirements of the work environment.","back":"Learn duties, reporting lines, attendance, equipment use, confidentiality, safety and expected conduct through induction and training. Clarify instructions and follow procedures rather than guessing or ignoring them.","objectiveCodes":["OA7.8"]},{"id":"oa-check-25","front":"What is the purpose of induction?","back":"It helps a new employee understand the organisation, duties, colleagues, procedures, safety requirements and expected conduct so they can begin working effectively.","objectiveCodes":["OA7.7","OA7.8"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s7-lesson-26','oa-section-7','Employee welfare and labour turnover','Workplace rules and employment legislation can protect areas such as health and safety, equality of opportunity, fair treatment, working conditions, pay-related requirements and agreed benefits. The detailed rights and procedures depend on the jurisdiction and employment arrangement. For an actual case, use the relevant current rules and authorised advice. In an examination, explain the benefit of the protection described rather than inventing legal figures.',25,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":45,"section":7,"objectiveCodes":["OA7.9","OA7.10"]},"lesson":{"introduction":"Workplace rules and employment legislation can protect areas such as health and safety, equality of opportunity, fair treatment, working conditions, pay-related requirements and agreed benefits. The detailed rights and procedures depend on the jurisdiction and employment arrangement. For an actual case, use the relevant current rules and authorised advice. In an examination, explain the benefit of the protection described rather than inventing legal figures.","objectives":["discuss the benefits of legislation related to workers’ welfare","discuss the factors that contribute to employee/labour turnover in an organisation"],"sections":[{"title":"How it works","paragraphs":["Welfare measures can improve well-being, attendance, morale and trust. Safe equipment, clear procedures, appropriate training, fair treatment and accessible ways to raise concerns help employees work effectively. These measures also benefit the organisation by reducing avoidable accidents, disruption and conflict. Welfare is not limited to occasional entertainment or gifts.","Labour turnover is the movement of employees into and out of an organisation, often discussed as employees leaving and needing replacement. Causes can include poor working conditions, low morale, limited advancement, unsuitable recruitment, relocation, retirement or better opportunities elsewhere. Some turnover is expected, but high avoidable turnover can increase recruitment and training costs, interrupt service and remove experience. Use attendance, exit information and other evidence to investigate causes before proposing improvements."]},{"title":"Connect a worker protection to its practical benefit","paragraphs":["A statutory protection is established by law; a workplace policy is an organisation’s own rule. Factory and occupational-safety requirements can address hazards, protective equipment, safe machinery and working conditions. The benefit is fewer injuries and a safer working environment, not merely a document kept in HR. The exact title and scope of the relevant law vary across Caribbean territories.","ILO conventions set international labour standards; their effect in a country depends on its ratification and implementation arrangements. A collective bargaining agreement records negotiated terms between the employer and the recognised workers’ representative. It can clarify agreed pay, hours, leave or dispute procedures, but should not be described as a law passed by Parliament.","When answering a scenario, link the protection to a result: supplying and correctly using required protective equipment helps reduce exposure to a stated hazard; a clear grievance process provides an orderly way to raise a workplace concern. Use current local sources for an actual entitlement and the figures supplied for a classroom calculation."]},{"title":"A practical office example","paragraphs":["A company repeatedly loses new clerks after one month. Exit information points to unclear duties and little training. Improving induction, supervision and role clarity addresses the reported cause more directly than simply offering another recruitment advertisement. Check whether the improvement reduces early departures."]},{"title":"Avoid this mistake","paragraphs":["Do not assume every departure proves poor management or that higher pay alone solves every turnover problem. Link the proposed action to evidence about the cause."]}],"keyPoints":["Workplace rules and employment legislation can protect areas such as health and safety, equality of opportunity, fair treatment, working conditions, pay-related requirements and agreed benefits.","Welfare measures can improve well-being, attendance, morale and trust.","Labour turnover is the movement of employees into and out of an organisation, often discussed as employees leaving and needing replacement."],"summary":"The organisation may incur repeated recruitment and training costs and lose experienced staff, causing disruption, lower efficiency or poorer customer service.","check":{"question":"Give two costs of high avoidable labour turnover.","answer":"The organisation may incur repeated recruitment and training costs and lose experienced staff, causing disruption, lower efficiency or poorer customer service."},"flashcards":[{"id":"OA7.9","front":"Discuss the benefits of legislation related to workers’ welfare.","back":"Appropriate workplace protections and welfare support safety, fair treatment, working conditions, morale and attendance. Specific rights and procedures depend on the applicable current rules and employment arrangement.","objectiveCodes":["OA7.9"]},{"id":"OA7.10","front":"Discuss the factors that contribute to employee/labour turnover in an organisation.","back":"Turnover can result from conditions, morale, recruitment fit, limited development, retirement, relocation or other opportunities. High avoidable turnover adds recruitment and training cost and disrupts service; investigate causes before proposing remedies.","objectiveCodes":["OA7.10"]},{"id":"oa-check-26","front":"Give two costs of high avoidable labour turnover.","back":"The organisation may incur repeated recruitment and training costs and lose experienced staff, causing disruption, lower efficiency or poorer customer service.","objectiveCodes":["OA7.9","OA7.10"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s8-lesson-27','oa-section-8','Inside the accounts office','The accounts office records and controls the organisation''s money transactions. It helps prepare invoices, collect amounts due, pay approved bills, maintain financial records, process payroll and provide information for decisions. Accounts payable concerns amounts owed to suppliers; accounts receivable concerns amounts owed by customers. These are not the same as money already paid or received.',26,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":49,"section":8,"objectiveCodes":["OA8.1","OA8.2","OA8.4"]},"lesson":{"introduction":"The accounts office records and controls the organisation''s money transactions. It helps prepare invoices, collect amounts due, pay approved bills, maintain financial records, process payroll and provide information for decisions. Accounts payable concerns amounts owed to suppliers; accounts receivable concerns amounts owed by customers. These are not the same as money already paid or received.","objectives":["describe the role and functions of the accounts office","describe the duties and attributes of a clerk in the accounts office","use hardware and software resources applicable to the accounts office"],"sections":[{"title":"How it works","paragraphs":["An accounts clerk checks documents, enters accurate data, files supporting evidence, prepares routine statements or schedules and refers discrepancies. Important attributes include honesty, accuracy, confidentiality, numeracy and the ability to follow procedures. Separate authorisation, custody and recording responsibilities where the system requires it: the person preparing a payment should not simply approve their own unsupported request.","Calculators, computers, spreadsheets, accounting software, scanners and secure payment systems can support the work. Use the correct formulas, account references, access rights and backup procedures. A spreadsheet produces an incorrect result if its input or formula is wrong. Reconcile totals and supporting documents rather than assuming a computer-generated figure is automatically reliable."]},{"title":"A practical office example","paragraphs":["A supplier invoice arrives for 20 cartridges, but the delivery record confirms only 18 accepted cartridges. The clerk checks the purchase order and receipt record and raises the discrepancy before authorising payment. Paying the full invoice without checking would weaken the control even if the amount was entered neatly into a spreadsheet."]},{"title":"Avoid this mistake","paragraphs":["An invoice requests payment; a receipt acknowledges payment. Do not describe every accounts task as simply ''handling cash'' or treat software as a substitute for authorised documents."]}],"keyPoints":["The accounts office records and controls the organisation''s money transactions.","An accounts clerk checks documents, enters accurate data, files supporting evidence, prepares routine statements or schedules and refers discrepancies.","Calculators, computers, spreadsheets, accounting software, scanners and secure payment systems can support the work."],"summary":"The match checks that the goods or services were ordered, received and charged on the agreed terms before payment is approved.","check":{"question":"Why should accounts match an invoice to the purchase order and receipt record?","answer":"The match checks that the goods or services were ordered, received and charged on the agreed terms before payment is approved."},"flashcards":[{"id":"OA8.1","front":"Describe the role and functions of the accounts office.","back":"Accounts records financial transactions, prepares and controls payment documents, collects amounts due, supports payroll and provides financial information. Accounts payable concerns suppliers owed; accounts receivable concerns customers owing.","objectiveCodes":["OA8.1"]},{"id":"OA8.2","front":"Describe the duties and attributes of a clerk in the accounts office.","back":"The clerk checks and enters data, prepares routine records and correspondence, files evidence and reports discrepancies. Honesty, accuracy, numeracy, confidentiality and compliance with authorisation procedures are essential.","objectiveCodes":["OA8.2"]},{"id":"OA8.4","front":"Use hardware and software resources applicable to the accounts office.","back":"Calculators, spreadsheets, accounting software, computers, scanners and secure payment systems support accounts work. Check formulas, input, access rights, backups and supporting documents; computer output is not automatically correct.","objectiveCodes":["OA8.4"]},{"id":"oa-check-27","front":"Why should accounts match an invoice to the purchase order and receipt record?","back":"The match checks that the goods or services were ordered, received and charged on the agreed terms before payment is approved.","objectiveCodes":["OA8.1","OA8.2","OA8.4"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s8-lesson-28','oa-section-8','Pay records, receipts and petty cash','Accounts documents create a traceable record of amounts and authorisation. A payslip identifies the pay period, earnings, deductions and net pay. Gross pay is total earnings before deductions; net pay is gross pay minus the stated deductions. Basic pay may be calculated from hours and an hourly rate; overtime uses the rate and multiplier given. Use authorised time records and the figures in the question rather than assuming a statutory deduction rate.',27,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":50,"section":8,"objectiveCodes":["OA8.3","OA8.10"]},"lesson":{"introduction":"Accounts documents create a traceable record of amounts and authorisation. A payslip identifies the pay period, earnings, deductions and net pay. Gross pay is total earnings before deductions; net pay is gross pay minus the stated deductions. Basic pay may be calculated from hours and an hourly rate; overtime uses the rate and multiplier given. Use authorised time records and the figures in the question rather than assuming a statutory deduction rate.","objectives":["prepare simple documents in the accounts office","prepare petty cash records"],"sections":[{"title":"How it works","paragraphs":["A receipt identifies the payer, date, amount, purpose, payment method or reference and the authorised recipient or issuing organisation. A payment voucher supports and authorises a payment; it should be linked to the appropriate evidence. Check both words and figures where a document uses both. Preserve the required copy and avoid issuing duplicate acknowledgements that could be mistaken for separate payments.","Petty cash covers authorised small expenses. Under an imprest system, the float is a fixed authorised amount. Record payments using petty cash vouchers and supporting receipts, analyse them into the required expense columns and check cash in hand against the record. Reimbursement normally restores the float by the amount properly spent. An unexplained shortage is a discrepancy to investigate, not an ordinary expense to invent."]},{"title":"Prepare the other everyday accounts documents","paragraphs":["A currency memorandum breaks a cash payment into denominations so the required notes and coins can be obtained or checked. Multiply each denomination by its quantity, then total the amounts. In an illustrative exercise, 6 notes of $2,000, 1 of $1,000, 2 of $200 and 1 of $50 total $13,450. The memorandum must agree with the authorised cash total; a convenient number of notes is not a substitute for that check.","A statement of account summarises the opening balance and transactions with a customer over a period. Start with the balance brought forward, add invoices or other valid charges, and subtract payments and accepted credit notes. An opening debt of $8,000 plus an invoice for $5,000, less a $3,000 payment and a $500 credit note, leaves $9,500 owing. Use the correct dates, references, account name and period.","A credit note issued by a seller normally reduces an amount previously charged, such as an accepted return or overcharge. A buyer may send a debit note to request that adjustment; some documents called debit notes instead record an additional charge. Identify who issued the document and its stated purpose before adjusting an account. For a cheque, enter the date, payee and matching amount in words and figures, obtain the authorised signature and complete the counterfoil or electronic record."]},{"title":"A practical office example","paragraphs":["A clerk earns $750 per hour for 40 basic hours and works four overtime hours at time-and-a-half. Basic pay is $30,000; overtime is 4 × $750 × 1.5 = $4,500; gross pay is $34,500. Given total deductions of $3,500, net pay is $31,000. Separately, a $5,000 petty cash float with $1,200 properly spent needs a $1,200 reimbursement to return to $5,000."]},{"title":"Avoid this mistake","paragraphs":["Do not subtract deductions twice or call gross pay the take-home amount. Replenishing an imprest float is not automatically a new full float in addition to the cash remaining."]}],"keyPoints":["Accounts documents create a traceable record of amounts and authorisation.","A receipt identifies the payer, date, amount, purpose, payment method or reference and the authorised recipient or issuing organisation.","Petty cash covers authorised small expenses."],"summary":"$4,000 − $850 = $3,150 should remain. A reimbursement of $850 restores the authorised float, assuming there is no discrepancy.","check":{"question":"A $4,000 imprest float has $850 in authorised vouchers. What cash should remain before reimbursement?","answer":"$4,000 − $850 = $3,150 should remain. A reimbursement of $850 restores the authorised float, assuming there is no discrepancy."},"flashcards":[{"id":"OA8.3","front":"Prepare simple documents in the accounts office.","back":"Complete pay records, receipts, vouchers and other routine documents with correct names, dates, references, amounts and authority. Gross pay is earnings before deductions; net pay is gross less deductions.","objectiveCodes":["OA8.3"]},{"id":"OA8.10","front":"Prepare petty cash records.","back":"Use authorised vouchers and receipts to record small expenses and analyse them into the required columns. Under an imprest system, reimbursement normally equals properly spent amounts and restores the fixed authorised float.","objectiveCodes":["OA8.10"]},{"id":"oa-check-28","front":"A $4,000 imprest float has $850 in authorised vouchers. What cash should remain before reimbursement?","back":"$4,000 − $850 = $3,150 should remain. A reimbursement of $850 restores the authorised float, assuming there is no discrepancy.","objectiveCodes":["OA8.3","OA8.10"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s8-lesson-29','oa-section-8','Financial institutions, payments and cheque controls','Financial institutions provide different services. Commercial banks commonly provide deposit, lending and payment services; credit unions are member-based financial cooperatives; building societies and other institutions specialise according to their functions and local arrangements. A central bank has a different role in the financial system from an ordinary customer''s retail banking office. Select an institution or service for the actual need, access, cost, terms and security rather than assuming all institutions offer identical products.',28,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":51,"section":8,"objectiveCodes":["OA8.5","OA8.6","OA8.7"]},"lesson":{"introduction":"Financial institutions provide different services. Commercial banks commonly provide deposit, lending and payment services; credit unions are member-based financial cooperatives; building societies and other institutions specialise according to their functions and local arrangements. A central bank has a different role in the financial system from an ordinary customer''s retail banking office. Select an institution or service for the actual need, access, cost, terms and security rather than assuming all institutions offer identical products.","objectives":["differentiate among types of Financial Institutions","outline the procedures for making and receiving different types of payments","differentiate among types of cheques"],"sections":[{"title":"How it works","paragraphs":["Payments may use cash, cheques, payment cards, transfers, direct debits, standing orders or electronic and mobile services. A standing order is an instruction to make scheduled payments under the agreed arrangement; a direct debit authorises collection under its terms. Check the payee, amount, reference, authority and evidence of completion. A transfer request or screenshot should be verified through the approved system before a receipt or release of goods is authorised.","Cheque terminology explains how a cheque is handled. The drawer issues the cheque, the drawee is the institution directed to pay and the payee is the intended recipient. Crossings and account-payee instructions affect collection under applicable practice. Post-dated, stale, dishonoured, stopped, certified or bank-issued cheques need to be distinguished by their purpose and status. Follow current banking rules for an actual payment; never invent a universal validity period. Protect blank stationery and signature authority."]},{"title":"Tell the financial institutions apart","paragraphs":["A commercial bank provides services such as deposits, loans and payments to customers. A credit union is a member-owned financial cooperative, providing services to eligible members under its rules. A central bank serves the monetary and financial system through responsibilities such as currency and monetary-policy functions; it is not simply another high-street bank for ordinary customer transactions.","An insurance company provides cover for specified risks in return for premiums, subject to the policy. An investment company pools or manages funds for investment under the arrangement offered. A mortgage company specialises in lending secured on property. A cambio or bureau de change exchanges currencies; its quoted buying and selling rates are not necessarily the same.","An offshore institution provides financial services from a jurisdiction to clients or business outside that jurisdiction under its applicable rules. The word offshore does not mean that the organisation is free from regulation or that the service is automatically suitable. Read the function described in a question rather than choosing an institution only because its name contains the word bank."]},{"title":"Follow a payment from authority to evidence","paragraphs":["For a cash payment, verify the amount and authority, count it carefully, obtain or issue the appropriate receipt and secure the money and records. With a payment card, confirm the approved amount and use the authorised terminal and verification procedure. Do not disclose a PIN or record payment credentials in an ordinary office message.","A money order or postal order is purchased from the issuing provider for a payment under its service conditions. A bank draft is issued by a bank for a specified amount. A credit transfer moves funds through the banking system to the recipient’s account. A standing order instructs scheduled payments under an agreed arrangement. A letter of credit requires compliance with its stated payment conditions, often including documents. Availability and processing details depend on the service.","For electronic transfers and mobile money, verify the authorised payee, account or wallet reference, amount and confirmation through the approved system. Keep the transaction reference and update the correct account. An unverified screenshot or a request to change a supplier’s banking details is not sufficient evidence that the payment is genuine or that the instruction is authorised."]},{"title":"Recognise the cheque by its features and status","paragraphs":["An open cheque is not crossed and may be payable over the counter subject to the bank’s checks. A crossed cheque bears a crossing that directs payment through an account rather than ordinary cash collection; additional words can restrict collection further. A counter cheque is supplied by a bank at the counter for use under its procedures rather than taken from the customer’s own printed cheque book.","A certified cheque has been certified by the bank under its procedure. A manager’s or bank-issued cheque is issued by the bank itself; do not assume the two arrangements are identical in every jurisdiction. A post-dated cheque carries a future date. A stale-dated cheque is too old to be accepted under the relevant banking rule. Do not assume one validity period applies to every country and transaction.","A cancelled cheque has been invalidated or marked to prevent further use in the context described. A dishonoured cheque has not been paid, for example because funds or another requirement are insufficient. A stop-payment instruction is a separate request to the bank. Read the question carefully: a crossing, a future date and a dishonour explain different features of a cheque."]},{"title":"A practical office example","paragraphs":["An email asks a clerk to change a supplier''s bank details immediately. Verify the request through an independent approved contact and follow the authorisation procedure. Replying to the same unverified email is not an independent check. When receiving a cheque, check the required date, payee, amount and authorisation before processing it."]},{"title":"Avoid this mistake","paragraphs":["A cheque is not cash already collected. Do not treat a standing order and direct debit as interchangeable or disclose account credentials to someone claiming to be the bank."]}],"keyPoints":["Financial institutions provide different services.","Payments may use cash, cheques, payment cards, transfers, direct debits, standing orders or electronic and mobile services.","Cheque terminology explains how a cheque is handled."],"summary":"A fraudulent or mistaken change could divert money. Independent verification and authorisation help confirm that the instruction came from the genuine supplier.","check":{"question":"Why should a change to supplier payment details be independently verified?","answer":"A fraudulent or mistaken change could divert money. Independent verification and authorisation help confirm that the instruction came from the genuine supplier."},"flashcards":[{"id":"OA8.5","front":"Differentiate among types of Financial Institutions.","back":"Commercial banks, credit unions, building societies, central banks and other institutions have different roles and services. Select for the actual need, cost, access, terms and security rather than treating them as identical.","objectiveCodes":["OA8.5"]},{"id":"OA8.6","front":"Outline the procedures for making and receiving different types of payments.","back":"Check payee, amount, reference, authority and actual completion for cash, cheque, card, transfer and other payments. Standing orders and direct debits have different instructions. Retain evidence and independently verify changed account details.","objectiveCodes":["OA8.6"]},{"id":"OA8.7","front":"Differentiate among types of cheques.","back":"Distinguish the drawer, drawee and payee and the effect of crossings or account-payee instructions. Post-dated, stale, dishonoured, stopped and bank-issued or certified cheques have different statuses and handling requirements.","objectiveCodes":["OA8.7"]},{"id":"oa-check-29","front":"Why should a change to supplier payment details be independently verified?","back":"A fraudulent or mistaken change could divert money. Independent verification and authorisation help confirm that the instruction came from the genuine supplier.","objectiveCodes":["OA8.5","OA8.6","OA8.7"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s8-lesson-30','oa-section-8','Read a bank statement and reconcile the cash book','The cash book records the organisation''s cash and bank transactions from its own viewpoint. A bank statement records transactions from the bank''s viewpoint. Read the column headings and the effect on the balance rather than assuming that a debit means the same thing in both records. Compare dates, amounts, cheque or transfer references, deposits and charges.',29,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":52,"section":8,"objectiveCodes":["OA8.8","OA8.9"]},"lesson":{"introduction":"The cash book records the organisation''s cash and bank transactions from its own viewpoint. A bank statement records transactions from the bank''s viewpoint. Read the column headings and the effect on the balance rather than assuming that a debit means the same thing in both records. Compare dates, amounts, cheque or transfer references, deposits and charges.","objectives":["interpret entries in a bank statement and a cash book","reconcile bank and cash book entries and balances"],"sections":[{"title":"How it works","paragraphs":["Differences may arise because the bank records items before the organisation does, because recorded items have not yet reached the bank, or because an error occurred. Update the cash book for genuine items not yet entered there, such as bank charges, interest, direct debits, standing orders or a dishonoured cheque. Correct the organisation''s errors using the proper procedure. Do not enter an outstanding cheque twice merely because it is absent from the statement.","Then reconcile the adjusted cash book balance with the statement. Starting with a positive bank statement balance, add deposits recorded in the cash book but not yet credited by the bank and subtract cheques issued but not yet presented. Apply the facts carefully if there is an overdraft or a bank error. The reconciliation explains differences; it does not force unrelated numbers to agree. Investigate any remaining unexplained amount."]},{"title":"A practical office example","paragraphs":["The statement shows $42,000. A $5,000 deposit is not yet credited, and an issued cheque for $3,000 is not yet presented. The comparable adjusted cash book balance is $42,000 + $5,000 − $3,000 = $44,000. If a $500 bank charge was absent from the cash book, update that record separately before comparing the balances."]},{"title":"Avoid this mistake","paragraphs":["Do not adjust the cash book for an outstanding cheque that is already recorded in it. Distinguish a timing difference from a missing entry or an error."]}],"keyPoints":["The cash book records the organisation''s cash and bank transactions from its own viewpoint.","Differences may arise because the bank records items before the organisation does, because recorded items have not yet reached the bank, or because an error occurred.","Then reconcile the adjusted cash book balance with the statement."],"summary":"The organisation has already recorded the payment, but the bank has not yet reduced the account for that cheque. Subtract it when reconciling from the statement balance.","check":{"question":"Why does an unpresented cheque make a positive bank statement balance higher than it would otherwise be?","answer":"The organisation has already recorded the payment, but the bank has not yet reduced the account for that cheque. Subtract it when reconciling from the statement balance."},"flashcards":[{"id":"OA8.8","front":"Interpret entries in a bank statement and a cash book.","back":"The cash book records the organisation’s transactions; the bank statement reflects the bank’s records. Compare headings, dates, amounts, references and balance effects rather than assuming debit and credit mean the same viewpoint.","objectiveCodes":["OA8.8"]},{"id":"OA8.9","front":"Reconcile bank and cash book entries and balances.","back":"Update the cash book for genuine missing bank items and errors, then explain timing differences. From a positive statement balance, add deposits not yet credited and subtract cheques not yet presented, applying the actual facts.","objectiveCodes":["OA8.9"]},{"id":"oa-check-30","front":"Why does an unpresented cheque make a positive bank statement balance higher than it would otherwise be?","back":"The organisation has already recorded the payment, but the bank has not yet reduced the account for that cheque. Subtract it when reconciling from the statement balance.","objectiveCodes":["OA8.8","OA8.9"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s9-lesson-31','oa-section-9','Procurement duties and responsible purchasing','Procurement obtains the goods and services the organisation needs. Its work includes identifying requirements, obtaining supplier information, comparing quotations, arranging authorised orders, following up delivery and coordinating with receiving, stores and accounts. Inventory management controls the goods held so that operations can continue without unnecessary cost or waste.',30,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":55,"section":9,"objectiveCodes":["OA9.1","OA9.3"]},"lesson":{"introduction":"Procurement obtains the goods and services the organisation needs. Its work includes identifying requirements, obtaining supplier information, comparing quotations, arranging authorised orders, following up delivery and coordinating with receiving, stores and accounts. Inventory management controls the goods held so that operations can continue without unnecessary cost or waste.","objectives":["describe the functions of the procurement and inventory management office","describe the duties and attributes of a clerk in the purchasing department"],"sections":[{"title":"How it works","paragraphs":["A purchasing clerk may prepare enquiries, record quotations, maintain supplier details, prepare orders under authority, track outstanding orders and investigate discrepancies. Accuracy, organisation, communication, integrity and commercial awareness are important. The clerk should protect confidential quotations, disclose conflicts through the appropriate procedure and avoid personal benefits that could distort a purchasing decision.","Separate a request from an approved order. A department can identify a need, but it does not automatically have permission to commit the organisation''s funds. Use the approved specifications and authorisation limits. Keep records of what was requested, approved, ordered and received so another officer can follow the transaction and verify payment."]},{"title":"A practical office example","paragraphs":["A department requests ten replacement chairs. Purchasing confirms the specifications and approval, obtains suitable quotations and records the authorised choice. If a supplier offers a personal gift to secure the order, the clerk follows the organisation''s conflict and gifts procedure rather than letting the offer determine the recommendation."]},{"title":"Avoid this mistake","paragraphs":["Procurement is more than buying the cheapest item. A purchase requisition is an internal request; a purchase order is an authorised instruction to a supplier."]}],"keyPoints":["Procurement obtains the goods and services the organisation needs.","A purchasing clerk may prepare enquiries, record quotations, maintain supplier details, prepare orders under authority, track outstanding orders and investigate discrepancies.","Separate a request from an approved order."],"summary":"Impartial handling supports a fair, evidence-based choice and protects the organisation from favouritism, conflicts and poor value.","check":{"question":"Why should supplier quotations be handled impartially?","answer":"Impartial handling supports a fair, evidence-based choice and protects the organisation from favouritism, conflicts and poor value."},"flashcards":[{"id":"OA9.1","front":"Describe the functions of the procurement and inventory management office.","back":"Procurement identifies needs, obtains supplier information, compares offers, arranges authorised orders and follows up supply. Inventory management controls stock availability, movement, condition and cost.","objectiveCodes":["OA9.1"]},{"id":"OA9.3","front":"Describe the duties and attributes of a clerk in the purchasing department.","back":"The clerk prepares enquiries and orders under authority, records quotations, maintains supplier details and follows up deliveries and discrepancies. Accuracy, impartiality, integrity and organisation support responsible purchasing.","objectiveCodes":["OA9.3"]},{"id":"oa-check-31","front":"Why should supplier quotations be handled impartially?","back":"Impartial handling supports a fair, evidence-based choice and protects the organisation from favouritism, conflicts and poor value.","objectiveCodes":["OA9.1","OA9.3"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s9-lesson-32','oa-section-9','Compare quotations and understand purchasing terms','Compare offers against the required quality, quantity, specification, delivery date, reliability, after-sales service, payment terms and total cost. A quotation states the supplier''s offer under specified conditions. Check how long it remains valid and whether delivery, packaging, insurance or other stated charges are included. Goods that arrive too late or fail the specification may cost more overall than a suitable higher-priced offer.',31,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":56,"section":9,"objectiveCodes":["OA9.2","OA9.4"]},"lesson":{"introduction":"Compare offers against the required quality, quantity, specification, delivery date, reliability, after-sales service, payment terms and total cost. A quotation states the supplier''s offer under specified conditions. Check how long it remains valid and whether delivery, packaging, insurance or other stated charges are included. Goods that arrive too late or fail the specification may cost more overall than a suitable higher-priced offer.","objectives":["interpret terms and abbreviations used in purchasing documents and literature","explain the factors influencing the purchasing of goods and services"],"sections":[{"title":"How it works","paragraphs":["A trade discount reduces a listed price according to the quoted terms; a cash or settlement discount rewards payment within specified conditions. Do not subtract a settlement discount from every invoice regardless of when payment occurs. Credit terms such as ''net 30 days'' specify the permitted time for payment. Cash on delivery requires payment under that delivery arrangement.","Abbreviations such as FOB and CIF relate to specified trade terms and responsibilities; read the named place and the terms supplied rather than assuming that every quotation includes the same transport or insurance. E&OE indicates errors and omissions excepted, not permission to ignore checking. In calculations, apply discounts and charges in the order specified and state the currency. Do not combine amounts in different currencies without the given conversion."]},{"title":"Read the abbreviation and the responsibility it describes","paragraphs":["FOB means Free On Board. Under the Incoterms rule for sea or inland-waterway transport, the seller delivers the goods on board the nominated vessel at the named shipment port; the buyer takes the subsequent risk and main transport responsibility under the rule. CIF means Cost, Insurance and Freight: the seller arranges and pays the required carriage and insurance to the named destination port, while risk normally transfers when the goods are loaded on board. Paying freight to the destination does not mean bearing every risk until arrival.","EXW means Ex Works: the seller makes goods available at the named premises under that rule, leaving major collection and transport responsibilities to the buyer. Always read the named place or port, agreed rule and version. COD means cash on delivery; CWO means cash with order. E&OE means errors and omissions excepted; it does not remove the need to check a quotation or correct an error.","VAT means Value Added Tax. Apply a tax only at the rate and on the base stated in the exercise; do not import another territory’s rate. Terms such as 2/10, n/30 mean a 2% settlement discount if the qualifying payment is made within ten days, otherwise the net amount is due within thirty days. On an eligible $10,000 balance, a 2% discount is $200, so timely payment is $9,800. Follow any stated rule about which charges qualify."]},{"title":"A practical office example","paragraphs":["Supplier A quotes 20 units at $1,000 each with 10% trade discount and $1,500 delivery. The goods cost $20,000 − $2,000 = $18,000; total quoted cost is $19,500 before any separately stated tax. Compare that with another supplier only after checking that quality, delivery date and included services match."]},{"title":"Avoid this mistake","paragraphs":["Do not select a supplier solely from the unit price or confuse a trade discount with a prompt-payment condition. A document abbreviation needs to be read in its transaction context."]}],"keyPoints":["Compare offers against the required quality, quantity, specification, delivery date, reliability, after-sales service, payment terms and total cost.","A trade discount reduces a listed price according to the quoted terms; a cash or settlement discount rewards payment within specified conditions.","Abbreviations such as FOB and CIF relate to specified trade terms and responsibilities; read the named place and the terms supplied rather than assuming that every quotation includes the same transport or insurance."],"summary":"The discount is 0.10 × $20,000 = $2,000, leaving $18,000 before any separately stated charges.","check":{"question":"How is a 10% trade discount calculated on a $20,000 list total?","answer":"The discount is 0.10 × $20,000 = $2,000, leaving $18,000 before any separately stated charges."},"flashcards":[{"id":"OA9.2","front":"Interpret terms and abbreviations used in purchasing documents and literature.","back":"Read prices and conditions carefully. Trade discount reduces a list price; settlement discount depends on payment terms. Net terms, cash on delivery and transport terms such as FOB or CIF affect the particular transaction.","objectiveCodes":["OA9.2"]},{"id":"OA9.4","front":"Explain the factors influencing the purchasing of goods and services.","back":"Compare specification, quality, quantity, delivery, reliability, total cost, payment conditions and support. The lowest unit price is not best value if the supply is unsuitable or arrives too late.","objectiveCodes":["OA9.4"]},{"id":"oa-check-32","front":"How is a 10% trade discount calculated on a $20,000 list total?","back":"The discount is 0.10 × $20,000 = $2,000, leaving $18,000 before any separately stated charges.","objectiveCodes":["OA9.2","OA9.4"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s9-lesson-33','oa-section-9','Follow the purchasing document trail','A typical purchase begins with an internal requisition identifying the need, quantity, specification, required date and requesting department. Purchasing checks authority and obtains suitable supplier information or quotations. After the approved choice, a purchase order states what the supplier is authorised to supply and the agreed terms. Keep a copy and use its reference in follow-up correspondence.',32,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":57,"section":9,"objectiveCodes":["OA9.5","OA9.6"]},"lesson":{"introduction":"A typical purchase begins with an internal requisition identifying the need, quantity, specification, required date and requesting department. Purchasing checks authority and obtains suitable supplier information or quotations. After the approved choice, a purchase order states what the supplier is authorised to supply and the agreed terms. Keep a copy and use its reference in follow-up correspondence.","objectives":["discuss the procedures for purchasing goods and acquiring services","prepare documents used in the purchase of goods and services"],"sections":[{"title":"How it works","paragraphs":["On delivery, the receiving officer checks the goods against the order and delivery documentation, records quantities and condition and reports shortages, damage or substitutions. A goods received note records what the organisation actually received and accepted. Signing a delivery document without checking can make a later discrepancy harder to establish.","Accounts compares the supplier invoice with the order and receipt evidence before approving payment. A credit note can correct or reduce an amount charged, for example after an agreed return or overcharge. A statement of account summarises the balance and transactions over a period; it is not the same as an invoice for a specific supply. Fill in dates, references, descriptions, quantities, prices and totals accurately on each document."]},{"title":"A practical office example","paragraphs":["An order requests 30 boxes, but only 28 undamaged boxes arrive. Record 28 accepted, note the two missing and notify the appropriate office and supplier. If the invoice charges for 30, resolve the discrepancy through the approved process rather than changing the physical receipt to match the invoice."]},{"title":"Avoid this mistake","paragraphs":["Do not record what was ordered as if it was automatically received. A delivery note is usually supplied with the goods; the goods received note is the receiving organisation''s record of its check."]}],"keyPoints":["A typical purchase begins with an internal requisition identifying the need, quantity, specification, required date and requesting department.","On delivery, the receiving officer checks the goods against the order and delivery documentation, records quantities and condition and reports shortages, damage or substitutions.","Accounts compares the supplier invoice with the order and receipt evidence before approving payment."],"summary":"Compare the authorised purchase order, evidence of goods or services received and the invoice details, then resolve discrepancies and obtain the required approval.","check":{"question":"What should be compared before paying a supplier invoice?","answer":"Compare the authorised purchase order, evidence of goods or services received and the invoice details, then resolve discrepancies and obtain the required approval."},"flashcards":[{"id":"OA9.5","front":"Discuss the procedures for purchasing goods and acquiring services.","back":"The usual trail moves from authorised requisition through supplier comparison and purchase order to checked receipt, invoice matching and approved payment. Resolve shortages, damage and price differences before treating the purchase as complete.","objectiveCodes":["OA9.5"]},{"id":"OA9.6","front":"Prepare documents used in the purchase of goods and services.","back":"Prepare requisitions, enquiries, orders and receipt records with accurate dates, references, specifications, quantities and terms. Match them to supplier invoices and use agreed credit notes for corrections.","objectiveCodes":["OA9.6"]},{"id":"oa-check-33","front":"What should be compared before paying a supplier invoice?","back":"Compare the authorised purchase order, evidence of goods or services received and the invoice details, then resolve discrepancies and obtain the required approval.","objectiveCodes":["OA9.5","OA9.6"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s9-lesson-34','oa-section-9','Control inventory and maintain stock records','Inventory is stock held for use or sale. Too little can stop work or cause lost sales; too much ties up funds, uses space and increases the risk of damage, theft or obsolescence. Good inventory management balances availability with cost. Consider usage, delivery lead time, reliability of supply, storage conditions and minimum or reorder levels.',33,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":58,"section":9,"objectiveCodes":["OA9.7","OA9.8"]},"lesson":{"introduction":"Inventory is stock held for use or sale. Too little can stop work or cause lost sales; too much ties up funds, uses space and increases the risk of damage, theft or obsolescence. Good inventory management balances availability with cost. Consider usage, delivery lead time, reliability of supply, storage conditions and minimum or reorder levels.","objectives":["discuss the importance of inventory management","maintain stock records using manual and electronic methods"],"sections":[{"title":"How it works","paragraphs":["A bin card records quantities received, issued and remaining for one item at its storage location. A stock card or inventory record may also include values and other information. Use authorised receipt and issue documents and record each movement promptly. The running balance equals the previous balance plus receipts minus issues. Identify the item and units clearly: ''boxes'' and ''individual units'' cannot be mixed without the correct conversion.","Stocktaking compares the physical count with the recorded balance. Investigate differences instead of adjusting a record without explanation. Apply appropriate stock rotation, check expiry or condition where relevant and protect stores against unauthorised access. Manual and electronic systems both need reliable input, controls and trained users. Automatic reorder alerts support the decision; they do not replace the organisation''s approval procedure."]},{"title":"Stock rotation, inventory costs and just-in-time supply","paragraphs":["FIFO means First-In-First-Out: the earliest available stock costs are assigned to the first issues. LIFO means Last-In-First-Out: the latest available costs are assigned first. AVCO means Average Cost: use the average unit cost for the available stock under the stated averaging procedure. A costing method assigns values; it does not by itself prove which physical carton was taken from a shelf. Follow the method and timing stated in the exercise.","Suppose stock consists of 10 units at $100 and a further 10 at $120, with no other transactions, and 12 units are issued. FIFO gives an issue cost of 10 × $100 + 2 × $120 = $1,240 and closing stock of 8 × $120 = $960. LIFO gives an issue cost of 10 × $120 + 2 × $100 = $1,400 and closing stock of 8 × $100 = $800. The weighted average is $2,200 ÷ 20 = $110 per unit: the issue costs $1,320 and closing stock is $880. In each case, issue cost plus closing value equals the $2,200 available cost.","Just-in-time supply aims to have items arrive close to when they are needed. It can reduce storage and money tied up in stock, but depends on dependable suppliers, accurate information and coordinated schedules. A late delivery can stop work. Barcode scanners and inventory software help identify movements quickly, while physical checks and authorised issue records help reveal pilferage, damage or entry errors."]},{"title":"A practical office example","paragraphs":["An item opens with 40 units. A receipt of 25 raises the balance to 65; an authorised issue of 18 reduces it to 47. If the reorder level is 15, this balance is above it. An attempted issue of 50 should be checked because only 47 units are recorded as available. Use the stock-record tool to see each movement and balance."]},{"title":"Avoid this mistake","paragraphs":["Do not count an order placed as stock already received. A reorder level tells the office when to consider ordering; it is not necessarily the quantity to order."]}],"keyPoints":["Inventory is stock held for use or sale.","A bin card records quantities received, issued and remaining for one item at its storage location.","Stocktaking compares the physical count with the recorded balance."],"summary":"40 + 25 − 18 = 47 units. The balance should also be checked against the physical stock under the stocktaking procedure.","check":{"question":"What is the new balance after opening stock of 40, a receipt of 25 and an issue of 18?","answer":"40 + 25 − 18 = 47 units. The balance should also be checked against the physical stock under the stocktaking procedure."},"flashcards":[{"id":"OA9.7","front":"Discuss the importance of inventory management.","back":"Good inventory control prevents avoidable shortages while reducing tied-up funds, waste, damage, theft and obsolescence. Consider usage, lead time, reorder levels, storage and authorised access.","objectiveCodes":["OA9.7"]},{"id":"OA9.8","front":"Maintain stock records using manual and electronic methods.","back":"Record receipts and issues promptly from authorised documents. The new quantity balance is previous stock plus receipts minus issues. Compare records with physical counts and investigate discrepancies; an order is not stock received.","objectiveCodes":["OA9.8"]},{"id":"oa-check-34","front":"What is the new balance after opening stock of 40, a receipt of 25 and an issue of 18?","back":"40 + 25 − 18 = 47 units. The balance should also be checked against the physical stock under the stocktaking procedure.","objectiveCodes":["OA9.7","OA9.8"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s10-lesson-35','oa-section-10','Sales, marketing and customer service work together','Marketing identifies customer needs and helps plan how suitable products or services reach the market. Sales handles enquiries, quotations, orders and the process of obtaining business. Customer service supports customers before, during and after a transaction and helps resolve enquiries and complaints. The functions overlap, but each has a distinct contribution.',34,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":61,"section":10,"objectiveCodes":["OA10.1","OA10.2","OA10.3"]},"lesson":{"introduction":"Marketing identifies customer needs and helps plan how suitable products or services reach the market. Sales handles enquiries, quotations, orders and the process of obtaining business. Customer service supports customers before, during and after a transaction and helps resolve enquiries and complaints. The functions overlap, but each has a distinct contribution.","objectives":["explain the functions of the sales, marketing and customer service offices","analyse the duties of a clerk in the sales, marketing and customer service offices","describe the skills required by a clerk in the sales, marketing and customer services offices"],"sections":[{"title":"How it works","paragraphs":["A clerk may maintain customer records, prepare correspondence and sales documents, process orders, update information, arrange follow-up and pass enquiries to the right officer. Useful skills include clear communication, product knowledge, accurate record keeping, numeracy, listening, patience, tact and competent use of the approved systems. Reliable information is more useful than an exaggerated promise.","When a customer complains, listen, establish the facts, acknowledge the concern and explain the next appropriate action. Check the order and service record, stay courteous and refer decisions outside your authority. Record the issue and agreed follow-up so the customer does not need to repeat the entire story. Complaint information can also show where the organisation''s product or process needs improvement."]},{"title":"A practical office example","paragraphs":["A customer reports that a delivery contains the wrong colour. The clerk checks the order reference, the agreed specification and the delivery record, then explains the approved correction process. Blaming the warehouse or promising an unauthorised refund does not resolve the matter professionally."]},{"title":"Avoid this mistake","paragraphs":["Customer service is not agreeing to every demand. Good service combines courtesy, accurate information, appropriate authority and reliable follow-up."]}],"keyPoints":["Marketing identifies customer needs and helps plan how suitable products or services reach the market.","A clerk may maintain customer records, prepare correspondence and sales documents, process orders, update information, arrange follow-up and pass enquiries to the right officer.","When a customer complains, listen, establish the facts, acknowledge the concern and explain the next appropriate action."],"summary":"The record supports follow-up, consistent handling and investigation of recurring faults that may need a wider process improvement.","check":{"question":"Why should a customer complaint be recorded even after the immediate problem is resolved?","answer":"The record supports follow-up, consistent handling and investigation of recurring faults that may need a wider process improvement."},"flashcards":[{"id":"OA10.1","front":"Explain the functions of the sales, marketing and customer service offices.","back":"Marketing identifies and serves market needs; sales handles enquiries and orders; customer service supports customers and resolves issues. Together they build reliable transactions and continuing customer relationships.","objectiveCodes":["OA10.1"]},{"id":"OA10.2","front":"Analyse the duties of a clerk in the sales, marketing and customer service offices.","back":"The clerk processes enquiries and orders, prepares documents, maintains records, coordinates information and follows up customer issues through the approved procedures and authority.","objectiveCodes":["OA10.2"]},{"id":"OA10.3","front":"Describe the skills required by a clerk in the sales, marketing and customer services offices.","back":"Useful skills include clear communication, listening, product knowledge, accuracy, numeracy, tact, patience, problem-solving and competent use of approved systems. Do not replace facts with exaggerated promises.","objectiveCodes":["OA10.3"]},{"id":"oa-check-35","front":"Why should a customer complaint be recorded even after the immediate problem is resolved?","back":"The record supports follow-up, consistent handling and investigation of recurring faults that may need a wider process improvement.","objectiveCodes":["OA10.1","OA10.2","OA10.3"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s10-lesson-36','oa-section-10','Prepare clear sales and marketing documents','A sales enquiry asks for information; a quotation gives an offered price and terms; an order records the customer''s request. An invoice lists the goods or services charged and the amount due. A delivery note accompanies a supply, while a receipt acknowledges a payment. A credit note reduces or corrects an amount charged under the agreed circumstances. Read the purpose before deciding which document to prepare.',35,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":64,"section":10,"objectiveCodes":["OA10.4"]},"lesson":{"introduction":"A sales enquiry asks for information; a quotation gives an offered price and terms; an order records the customer''s request. An invoice lists the goods or services charged and the amount due. A delivery note accompanies a supply, while a receipt acknowledges a payment. A credit note reduces or corrects an amount charged under the agreed circumstances. Read the purpose before deciding which document to prepare.","objectives":["prepare documents used in sales and marketing"],"sections":[{"title":"How it works","paragraphs":["Check customer and supplier names, dates, item descriptions, quantities, unit prices, discounts, charges, totals, payment terms and references. If a document continues over several lines, make sure the total includes every relevant item once. Write the currency where ambiguity is possible. An attractive document with the wrong customer reference can still cause delay or an incorrect account.","Marketing materials such as notices, brochures, price lists and advertisements should give accurate, relevant information to the intended audience. Use clear headings, readable details and an appropriate contact or response method. Check the authority for prices, claims and publication. Do not add a delivery promise, guarantee or discount that the organisation has not approved."]},{"title":"Prepare a proforma invoice, press release or survey for its purpose","paragraphs":["A proforma invoice sets out the proposed goods, prices and terms before the ordinary final invoice is issued. It may be used to provide information or support an advance-payment arrangement. Label it clearly and do not treat it as proof that the goods were delivered or the account paid. An e-invoice still needs the correct parties, date, unique reference, quantities, charges and total.","A flyer or advertisement needs the intended audience, accurate offer, essential dates or conditions and a clear way to respond. A press release presents authorised information for the media: identify the organisation, release date, subject, key facts and a contact for enquiries. Put the main news early and verify any quotation or claim before publication.","A survey collects comparable information from respondents. Link questions to the research purpose, use clear neutral wording and choose answer options that make sense. “How satisfied are you with delivery time?” is more useful than “Do you agree our excellent delivery service is perfect?” Do not request private details that the investigation does not need."]},{"title":"A practical office example","paragraphs":["An invoice contains 12 items at $850 and a delivery charge of $1,000, with no other charges stated. The goods total is $10,200 and the invoice total is $11,200. Before sending it, confirm that the quantity and price match the approved order and that the invoice has a unique reference."]},{"title":"Avoid this mistake","paragraphs":["A quotation is not evidence that a sale has already been completed. A receipt should not be issued as if payment was collected merely because an invoice was prepared."]}],"keyPoints":["A sales enquiry asks for information; a quotation gives an offered price and terms; an order records the customer''s request.","Check customer and supplier names, dates, item descriptions, quantities, unit prices, discounts, charges, totals, payment terms and references.","Marketing materials such as notices, brochures, price lists and advertisements should give accurate, relevant information to the intended audience."],"summary":"It records the reduction or correction to the amount charged and provides evidence for updating the relevant account.","check":{"question":"What is the purpose of a credit note issued after an agreed overcharge?","answer":"It records the reduction or correction to the amount charged and provides evidence for updating the relevant account."},"flashcards":[{"id":"OA10.4","front":"Prepare documents used in sales and marketing.","back":"Prepare quotations, orders, invoices, delivery records, receipts, credit notes and marketing materials for their distinct purposes. Check quantities, prices, totals, references, terms, contacts and approved claims.","objectiveCodes":["OA10.4"]},{"id":"oa-check-36","front":"What is the purpose of a credit note issued after an agreed overcharge?","back":"It records the reduction or correction to the amount charged and provides evidence for updating the relevant account.","objectiveCodes":["OA10.4"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s10-lesson-37','oa-section-10','Corporate communication and customer incentives','Corporate communication helps the organisation give accurate, consistent information to its stakeholders. A communications clerk can prepare or distribute authorised notices, maintain contact and media records, monitor enquiries, organise information for events and support internal and external communication. Messages should reflect the organisation''s approved position, especially when an issue is sensitive or attracts public attention.',36,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":64,"section":10,"objectiveCodes":["OA10.5","OA10.6"]},"lesson":{"introduction":"Corporate communication helps the organisation give accurate, consistent information to its stakeholders. A communications clerk can prepare or distribute authorised notices, maintain contact and media records, monitor enquiries, organise information for events and support internal and external communication. Messages should reflect the organisation''s approved position, especially when an issue is sensitive or attracts public attention.","objectives":["outline the functions of the Corporate Communications Clerk","distinguish among the different types of incentives"],"sections":[{"title":"How it works","paragraphs":["Verify facts, dates, names and authority before publication. Direct a media enquiry to the designated spokesperson rather than guessing an answer. Use professional language, protect confidential information and keep a record of issued material. The same care applies to a public website, social-media post, printed notice or internal bulletin. A quickly published error can damage trust even if the design looks polished.","Incentives encourage customers or sales staff to take a desired action. Customer incentives can include discounts, loyalty benefits, samples, gifts or promotional offers. Sales-force incentives may include commission, bonuses, recognition or other rewards. Compare the purpose, cost, conditions and likely effect. Explain an offer''s limits accurately and avoid confusing a temporary promotion with a permanent price or entitlement."]},{"title":"Recognise the communications clerk’s specific outputs","paragraphs":["Corporate communication can include a company newsletter, magazine, calendar, website and social-media content. The clerk may help gather accurate material, organise publication and keep approved information up to date. Planning staff or public activities and coordinating sponsorship for corporate-social-responsibility events also fall within the syllabus examples. Keep a record of permissions and refer sensitive public statements to the authorised spokesperson."]},{"title":"Distinguish discounts, promotions and consignment","paragraphs":["A trade discount reduces the listed price for an eligible trade customer or transaction. A quantity discount rewards the volume bought. A cash or settlement discount depends on paying within the stated period. A coupon gives its holder the stated benefit only when its conditions are met. A loyalty or membership scheme rewards qualifying participation or repeat purchases; a gift with purchase adds a specified item to an eligible sale.","Under a usual consignment arrangement, a supplier places goods with a dealer to sell on the agreed terms while retaining ownership until sale. This can encourage a dealer to stock goods without buying all of them outright in advance. Follow the actual agreement for payment, unsold stock, loss and commission. Consignment is an arrangement for holding and selling goods; it is not simply another percentage discount."]},{"title":"A practical office example","paragraphs":["A promotional offer gives a discount only on orders placed before a stated date and above a stated value. The clerk checks those conditions before preparing the price list or responding to an enquiry. If a journalist asks about an unrelated company incident, the clerk records the enquiry and refers it to the authorised spokesperson."]},{"title":"Avoid this mistake","paragraphs":["Do not give every customer a discount simply because a promotion exists. Corporate communication does not authorise every clerk to speak publicly on all business matters."]}],"keyPoints":["Corporate communication helps the organisation give accurate, consistent information to its stakeholders.","Verify facts, dates, names and authority before publication.","Incentives encourage customers or sales staff to take a desired action."],"summary":"A loyalty incentive encourages a customer''s repeat business. A commission rewards a salesperson according to the specified sales arrangement.","check":{"question":"How does a loyalty incentive differ from a sales commission?","answer":"A loyalty incentive encourages a customer''s repeat business. A commission rewards a salesperson according to the specified sales arrangement."},"flashcards":[{"id":"OA10.5","front":"Outline the functions of the Corporate Communications Clerk.","back":"The corporate communications clerk supports accurate authorised messages, notices, contact records, events and media enquiries. Verify facts and refer sensitive or public statements to the designated spokesperson.","objectiveCodes":["OA10.5"]},{"id":"OA10.6","front":"Distinguish among the different types of incentives.","back":"Customer incentives encourage purchases or repeat business through offers, discounts or loyalty benefits. Sales-force incentives reward staff through arrangements such as commission, bonuses or recognition. Apply the actual conditions.","objectiveCodes":["OA10.6"]},{"id":"oa-check-37","front":"How does a loyalty incentive differ from a sales commission?","back":"A loyalty incentive encourages a customer''s repeat business. A commission rewards a salesperson according to the specified sales arrangement.","objectiveCodes":["OA10.5","OA10.6"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s11-lesson-38','oa-section-11','Coordinate operations, dispatch and transport','Operations organises the work needed to produce goods or provide services. Dispatch prepares and sends goods to the correct destination, while transport arranges their movement. These offices coordinate with sales, purchasing, stores, accounts and customers. A correct order that is dispatched to the wrong place has still failed to meet the customer''s need.',37,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":66,"section":11,"objectiveCodes":["OA11.1","OA11.2"]},"lesson":{"introduction":"Operations organises the work needed to produce goods or provide services. Dispatch prepares and sends goods to the correct destination, while transport arranges their movement. These offices coordinate with sales, purchasing, stores, accounts and customers. A correct order that is dispatched to the wrong place has still failed to meet the customer''s need.","objectives":["explain the functions of the operations, dispatch and transport office","explain the duties of a clerk in the operations, dispatch and transport offices"],"sections":[{"title":"How it works","paragraphs":["Clerical duties can include maintaining schedules, preparing movement documents, checking order and delivery details, communicating instructions, recording vehicle or driver information, tracking consignments and following up delays. Accuracy, organisation, communication, safety awareness and the ability to work to deadlines are important. Use the approved procedure for damaged, missing or delayed goods.","Plan dispatch around the correct item, quantity, packaging, destination, delivery time, carrier and required documents. Consider route, capacity, product handling, cost, security and available resources. Urgency should not remove a required check or encourage unsafe transport. Keep authorised people informed when a delay changes the expected delivery."]},{"title":"A practical office example","paragraphs":["A food wholesaler has two deliveries with different storage needs. The dispatch clerk checks product handling, quantities, delivery addresses and available transport rather than loading both simply because the vehicle has space. If a delivery cannot meet the agreed time, communicate through the approved channel and record the revised arrangement."]},{"title":"Avoid this mistake","paragraphs":["Dispatch is not complete when goods leave the building. The organisation still needs appropriate tracking, acknowledgement and handling of any discrepancy."]}],"keyPoints":["Operations organises the work needed to produce goods or provide services.","Clerical duties can include maintaining schedules, preparing movement documents, checking order and delivery details, communicating instructions, recording vehicle or driver information, tracking consignments and following up delays.","Plan dispatch around the correct item, quantity, packaging, destination, delivery time, carrier and required documents."],"summary":"Sales may hold the agreement made with the customer. Coordinating prevents conflicting promises and allows the customer to receive accurate information about the change.","check":{"question":"Why should dispatch coordinate with sales before changing a delivery arrangement?","answer":"Sales may hold the agreement made with the customer. Coordinating prevents conflicting promises and allows the customer to receive accurate information about the change."},"flashcards":[{"id":"OA11.1","front":"Explain the functions of the operations, dispatch and transport office.","back":"Operations coordinates production or service work; dispatch prepares and sends goods; transport arranges their movement. Coordination with stores, sales and accounts supports correct, timely delivery.","objectiveCodes":["OA11.1"]},{"id":"OA11.2","front":"Explain the duties of a clerk in the operations, dispatch and transport offices.","back":"The clerk maintains schedules and movement records, checks consignment details, communicates instructions, tracks deliveries and reports problems. Accuracy, organisation, communication and safety awareness are important.","objectiveCodes":["OA11.2"]},{"id":"oa-check-38","front":"Why should dispatch coordinate with sales before changing a delivery arrangement?","back":"Sales may hold the agreement made with the customer. Coordinating prevents conflicting promises and allows the customer to receive accurate information about the change.","objectiveCodes":["OA11.1","OA11.2"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('office-administration','oa-s11-lesson-39','oa-section-11','Complete transport and dispatch documents','Movement documents identify what is being sent, by whom, to whom and under which service. Depending on the transaction, records may include a delivery note, dispatch book, consignment note, waybill, shipping instruction, transport schedule, vehicle log or relevant customs and shipping documents. A bill of lading and an air waybill serve transport-specific functions; use the document and facts given in the question rather than treating every movement record as identical.',38,true,'{"syllabus":{"source":"CXC 27/O/SYLL 24","sourcePage":68,"section":11,"objectiveCodes":["OA11.3","OA11.4"]},"lesson":{"introduction":"Movement documents identify what is being sent, by whom, to whom and under which service. Depending on the transaction, records may include a delivery note, dispatch book, consignment note, waybill, shipping instruction, transport schedule, vehicle log or relevant customs and shipping documents. A bill of lading and an air waybill serve transport-specific functions; use the document and facts given in the question rather than treating every movement record as identical.","objectives":["interpret information on documents used in operations, dispatch and transport","prepare documents used in operations, dispatch and transport"],"sections":[{"title":"How it works","paragraphs":["Read and enter sender and consignee details, dates, collection and delivery points, package counts, descriptions, weights, references, carrier information and any special handling instructions. The consignee is the intended receiver. Check that quantities and descriptions agree with the authorised order and actual consignment. Do not sign a blank document or acknowledge an unchecked quantity as correct.","Retain the required copies and proof of dispatch or delivery. A vehicle or journey log can record dates, locations, times, distance readings, fuel and other required details. Accurate records support planning, cost control, tracing goods and investigating discrepancies. If an instruction is unclear or a package count differs, resolve it through the appropriate officer before completing the record as if nothing was wrong."]},{"title":"Distinguish the transport documents before completing them","paragraphs":["A delivery schedule plans when deliveries are to take place. A destination sheet lists the required delivery locations and related route information. A delivery note identifies the goods supplied to a customer and can support an acknowledgement of the actual quantity received. An advice note tells the recipient that goods have been dispatched or are on the way; it is not proof that they arrived.","A maritime bill of lading acknowledges goods received for carriage and provides evidence of the carriage contract; a negotiable form can also serve as a document of title. Do not assume every transport document is negotiable. An air waybill records the air-cargo arrangement and is non-negotiable. A manifest is a summary list of cargo carried on a vessel, aircraft or other transport movement, rather than one customer’s ordinary sales invoice.","A customs form declares the required information about goods to the relevant authority. A certificate of origin states the country in which goods originate, not merely the port from which they were shipped. An import or export licence authorises a regulated transaction where required. An insurance certificate provides evidence of the cover specified, subject to its terms. A freight note records relevant transport charges.","When completing a form, work from the authorised order and the actual consignment. Check shipper and consignee, dates, references, package count, description, weight, destination and handling instructions. A false country of origin or an unchecked package count can cause a serious delay even when every box on the form has been filled. Retain the required copies and obtain the proper acknowledgement."]},{"title":"A practical office example","paragraphs":["A consignment contains six sealed cartons for Harbour Supplies, but the transport form lists eight. Check the physical count and supporting documents and correct the authorised record before dispatch. On delivery, obtain the required acknowledgement for the actual consignment and retain it with the matching reference."]},{"title":"Avoid this mistake","paragraphs":["Do not confuse the consignee with the carrier or assume a dispatch record proves that the goods were received. Read whether a document records instructions, acceptance for transport or completed delivery."]}],"keyPoints":["Movement documents identify what is being sent, by whom, to whom and under which service.","Read and enter sender and consignee details, dates, collection and delivery points, package counts, descriptions, weights, references, carrier information and any special handling instructions.","Retain the required copies and proof of dispatch or delivery."],"summary":"It provides an accurate record of what the carrier accepts and helps identify loss, shortage or a documentation error during transport and delivery.","check":{"question":"Why should the package count on a consignment note be checked against the goods?","answer":"It provides an accurate record of what the carrier accepts and helps identify loss, shortage or a documentation error during transport and delivery."},"flashcards":[{"id":"OA11.3","front":"Interpret information on documents used in operations, dispatch and transport.","back":"Interpret delivery notes, consignment notes, waybills, dispatch records, shipping instructions and logs according to purpose. Identify sender, consignee, carrier, date, quantity, route, reference and handling details.","objectiveCodes":["OA11.3"]},{"id":"OA11.4","front":"Prepare documents used in operations, dispatch and transport.","back":"Enter checked sender and consignee details, descriptions, quantities, packages, dates, carrier and special instructions. Retain required copies and acknowledgements. Resolve discrepancies before signing a document as correct.","objectiveCodes":["OA11.4"]},{"id":"oa-check-39","front":"Why should the package count on a consignment note be checked against the goods?","back":"It provides an accurate record of what the carrier accepts and helps identify loss, shortage or a documentation error during transport and delivery.","objectiveCodes":["OA11.3","OA11.4"]}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
